/**
 * Your 8 Grand Exchange slots, laid out 4 x 2 like the clerk's own screen,
 * drawn as the item actually in each one with a fill bar underneath showing
 * how much of that offer has completed.
 *
 * It used to be 8 flat colour swatches. Colour alone told you a slot was
 * busy but not WHAT was in it or how close it was to done — which is the
 * whole reason you'd glance at the GE while doing something else. An empty
 * slot is still just an outline, so "how many slots are free" stays
 * readable at a glance too.
 */
public class GeSlotsPanel extends JPanel
{
	public enum SlotState
	{
		/** Nothing in this slot. */
		EMPTY,
		/** Buying or selling, and the advisor still considers the price
		 *  competitive. */
		ACTIVE_OK,
		/** Buying or selling, but the price has drifted off the market —
		 *  matches the sidebar's own ADJUST_BUY/ADJUST_SELL suggestions. */
		ACTIVE_ADJUST,
		/** Fully bought/sold (or cancelled with something to collect) —
		 *  nothing left to do but collect it. */
		READY_COLLECT
	}

	public static class SlotInfo
	{
		public SlotState state = SlotState.EMPTY;
		public String itemName;
		public int itemId;
		/** Units filled so far and the offer's total, for the progress bar.
		 *  Both 0 on an empty slot. */
		public int quantityFilled;
		public int quantityTotal;
		public boolean buy;
		/** True when you have right-clicked this slot and told the plugin you
		 *  are pricing this one yourself. The slot keeps its sprite and its
		 *  fill bar, but outline and bar both go muted — the same grey the
		 *  in-game GE box takes — and it stops being flagged as needing a new
		 *  price. */
		public boolean adviceSkipped;
		/** What this offer is listed at, and what the plugin thinks it should
		 *  be listed at. Both 0 when there is nothing to say.
		 *
		 *  A red slot used to say only "needs a new price", which is half an
		 *  instruction: it names a problem and not the fix, and the obvious
		 *  reading of a red box is "cancel this". Somebody did, repriced at
		 *  the same number, and was rightly annoyed. The tooltip now names
		 *  the number to move to. */
		public long offerPrice;
		public long targetPrice;
		/** True when the flip no longer clears the tax at the new price —
		 *  i.e. repricing would fill you into a loser. Then the honest advice
		 *  is not "reprice", it is "take a different flip". */
		public boolean noMargin;
	}

	/** What this strip can ask the plugin to do. */
	public interface Actions
	{
		/** Turn "leave this offer's price alone" on or off for one slot. */
		void setSlotAdviceSkipped(int slot, boolean skipped);
		/** Show the item in this slot in the inspection card above — the same
		 *  thing a watchlist row or a finder row does when clicked. The eight
		 *  squares name the items you have the most riding on right now, and
		 *  until this they were the one place in the panel where clicking an
		 *  item did nothing at all. */
		void inspectItem(int itemId, String name);
	}

	/* Package-private, and the canonical copies: the bank overlay, the
	   in-game offer grid and the settings legend all paint or explain these
	   same FOUR, and a legend that drifts from what is on screen is worse
	   than no legend. */
	static final Color OK_COLOR = new Color(0x1F, 0xB8, 0x5C);
	static final Color ADJUST_COLOR = new Color(0xEF, 0x53, 0x50);
	static final Color COLLECT_COLOR = new Color(0xE5, 0xC1, 0x58);
	/** Muted outline for a slot you have opted out of advice on — the same
	 *  grey GeOfferGridOverlay paints on the in-game box, so the strip and
	 *  the Exchange window say the same thing about the same slot. It used to
	 *  only say it in one of the two places. */
	static final Color MUTED_COLOR = new Color(0x8A, 0x82, 0x74);
	/* Package-private, like OK_COLOR and the rest: the settings legend
	   draws a swatch for this border and must read it off the class that
	   paints it. It was the one legend row carrying a retyped colour, and
	   it drifted the moment the slot grid moved to the brand palette. */
	static final Color EMPTY_BORDER = Brand.BORDER_LIGHT;
	private static final Color TRACK = new Color(0x2B, 0x26, 0x21);
	/* 4 across, 2 down — the same arrangement the Grand Exchange clerk's own
	   interface uses. As a single row of 8 in a 225px sidebar each cell got
	   24px, narrower than the 36x32 item sprite it had to draw, so every slot
	   was a squashed thumbnail you couldn't identify without the tooltip.
	   Measured at 4 columns: 49x37 per cell, enough for the sprite at full
	   size — and, more to the point, a slot in the top-left of this panel is
	   the slot in the top-left of the GE window, so you can map one to the
	   other without counting. */
	private static final int COLS = 4;
	private static final int ROWS = 2;
	private static final int CELL = 32;
	private static final int BAR_H = 3;
	/* Both trimmed: the strip sat in more air than a row of eight 32px
	   squares needs, and the search box under it had its own strut on top
	   of this pad. Two pixels between the rows still separates them; three
	   under the strip is enough to keep the bottom bars off the box. */
	private static final int VGAP = 2;
	private static final int BOTTOM_PAD = 3;

	private final ItemManager itemManager;
	private final Actions actions;
	private final Cell[] cells = new Cell[COLS * ROWS];

	public GeSlotsPanel(ItemManager itemManager, Actions actions)
	{
		this.itemManager = itemManager;
		this.actions = actions;
		setLayout(new GridLayout(ROWS, COLS, 3, VGAP));
		setOpaque(false);
		setBorder(BorderFactory.createEmptyBorder(0, 0, BOTTOM_PAD, 0));
		// setPreferredSize is absolute — it INCLUDES the border, so the pad has
		// to be added here or GridLayout quietly takes it out of the cells and
		// each sprite gets squeezed a few pixels short of its 32px height.
		final int rowH = CELL + BAR_H + 2;
		final int totalH = ROWS * rowH + (ROWS - 1) * VGAP + BOTTOM_PAD;
		// Preferred width 0, NOT Short.MAX_VALUE. A preferred width of 32767
		// propagates up through FavoritesPanel into the scroll view, and a
		// JViewport sizes a non-Scrollable view to max(viewport, preferred) —
		// so one bad preferred width made the entire sidebar column 32767px
		// wide. Only the MAXIMUM should be unbounded.
		setPreferredSize(new Dimension(0, totalH));
		setMaximumSize(new Dimension(Short.MAX_VALUE, totalH));
		setToolTipText("Your 8 Grand Exchange offer slots — the bar under each shows how much of that offer has filled");
		for (int i = 0; i < cells.length; i++)
		{
			cells[i] = new Cell(i);
			add(cells[i]);
		}
	}

	/** Call on the EDT. Fewer than 8 entries just leaves the tail empty. */
	public void update(SlotInfo[] slots)
	{
		for (int i = 0; i < cells.length; i++)
		{
			cells[i].set((slots != null && i < slots.length) ? slots[i] : null);
		}
		revalidate();
		repaint();
	}

	/** One slot: the item's sprite with a progress bar drawn beneath it.
	 *  The bar is painted rather than a JProgressBar so it can be 3px tall
	 *  and take the slot's own status colour without fighting the look and
	 *  feel. */
	/**
	 * How far along an offer is, as a percentage string.
	 *
	 * Two decimals below 1%, whole numbers above it. A 4-hour limit is often
	 * five figures, so the first fills of a big offer are a fraction of a
	 * percent — 138 of 18,000 is 0.77%, and as an integer that floored to a
	 * flat "0%", which says "nothing has happened" about an offer that has
	 * genuinely started. The two ends of the range need different precision.
	 *
	 * Nothing filled still reads "0", because 0.00% for an offer that has not
	 * moved is false precision. And anything short of complete stops at 99:
	 * 35,999 of 36,000 rounds to 100% and reads as finished when it is not,
	 * which is the one misreading that sends you to the GE for nothing.
	 *
	 * Static and package-private so the boundaries can be tested — they are
	 * where every version of this has gone wrong.
	 */
	static String percentText(int filled, int total)
	{
		if (total <= 0 || filled <= 0)
		{
			return "0";
		}
		if (filled >= total)
		{
			return "100";
		}
		final double pct = 100.0 * filled / total;
		if (pct >= 1.0)
		{
			return String.valueOf(Math.min(99, (int) pct));
		}
		/* Floors rather than rounds, but never below 0.01: a single item out
		   of a huge limit is a real fill and must not report as zero. */
		final double floored = Math.floor(pct * 100) / 100.0;
		return String.format("%.2f", Math.max(0.01, floored));
	}

	private class Cell extends JPanel
	{
		private final JLabel icon = new JLabel();
		private final int slot;
		private SlotInfo info;

		Cell(int slot)
		{
			this.slot = slot;
			setLayout(new BorderLayout());
			setOpaque(false);
			// Keeps the sprite clear of the progress bar painted along the
			// bottom edge — BorderLayout.CENTER otherwise centres the icon in
			// the cell's FULL height and a 32px sprite runs into the bar.
			setBorder(BorderFactory.createEmptyBorder(0, 0, BAR_H + 2, 0));
			icon.setHorizontalAlignment(SwingConstants.CENTER);
			icon.setPreferredSize(new Dimension(CELL, CELL));
			add(icon, BorderLayout.CENTER);
			/* Built fresh on each right-click rather than once up front,
			   because the entry has to read the slot's CURRENT state \u2014 the
			   same cell is "stop advising" one minute and "resume" the next,
			   and a menu built at construction time would be stale by then.
			   Popup triggers differ per platform (press on Linux, release on
			   Windows), so both are checked. */
			final MouseAdapter menu = new MouseAdapter()
			{
				@Override public void mousePressed(MouseEvent e) { maybeShow(e); }
				@Override public void mouseReleased(MouseEvent e) { maybeShow(e); }

				/* Left-click inspects, matching the watchlist and the finder.
				   The popup trigger is checked first because on Linux a
				   right-click arrives as a press with isPopupTrigger set, and
				   SwingUtilities.isRightMouseButton alone would let a
				   context-menu click also swap the card underneath it. */
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (e.isPopupTrigger() || SwingUtilities.isRightMouseButton(e) || !inspectable())
					{
						return;
					}
					actions.inspectItem(info.itemId, info.itemName);
				}

				private void maybeShow(MouseEvent e)
				{
					if (!e.isPopupTrigger() || actions == null
						|| info == null || info.state == SlotState.EMPTY)
					{
						return;
					}
					final boolean skipped = info.adviceSkipped;
					final JPopupMenu popup = new JPopupMenu();
					final JMenuItem toggle = new JMenuItem(skipped
						? "Resume price advice for this offer"
						: "Ignore advice \u2014 I'm pricing this one myself");
					toggle.setToolTipText(skipped
						? "Go back to being told when this offer's price has drifted off the market"
						: "Stop being told to reprice this offer. For when you are deliberately "
							+ "asking more than the market pays \u2014 an overnight sell, say \u2014 or "
							+ "bidding under it and content to wait.");
					toggle.addActionListener(a -> actions.setSlotAdviceSkipped(slot, !skipped));
					popup.add(toggle);
					popup.show(Cell.this, e.getX(), e.getY());
				}
			};
			addMouseListener(menu);
			icon.addMouseListener(menu);
		}

		/** Whether clicking this cell has anything to show. The name matters
		 *  as much as the id: the inspection card is rebuilt from a Row keyed
		 *  by name, so a nameless slot would open a card that never prices. */
		private boolean inspectable()
		{
			return actions != null && info != null && info.state != SlotState.EMPTY
				&& info.itemId > 0 && info.itemName != null && !info.itemName.isEmpty();
		}

		void set(SlotInfo next)
		{
			this.info = next;
			icon.setIcon(null);
			if (next != null && next.itemId > 0 && itemManager != null)
			{
				/* Same null guard as the other panels: no item sprites on the
				   login screen, and an NPE inside this loop would drop the
				   remaining slots rather than one icon. */
				final AsyncBufferedImage img = itemManager.getImage(next.itemId);
				if (img != null)
				{
					img.addTo(icon);
				}
			}
			final Cursor cursor = Cursor.getPredefinedCursor(
				inspectable() ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR);
			setCursor(cursor);
			icon.setCursor(cursor);
			final String tip = describe(next);
			setToolTipText(tip);
			/*
			 * The sprite needs it too, and that is not belt and braces.
			 *
			 * ToolTipManager attaches itself per component, to each one that
			 * has had setToolTipText called on it — it does NOT walk up to a
			 * parent for a component that has none. This label fills the
			 * cell's CENTER, so it is what the pointer is actually over
			 * essentially always, and the cell's own tooltip could only ever
			 * appear in the two-pixel margin around the edge. Which is why
			 * hovering an offer to see how far it had filled appeared to do
			 * nothing at all: the text was there, on a component nobody could
			 * reach.
			 */
			icon.setToolTipText(tip);
			repaint();
		}

		/**
		 * What this square is, what to do about it, and how far along it is —
		 * one short line each.
		 *
		 * This was a single run-on sentence: "Selling Ruby — 4,000 of 12,328
		 * (32%) (needs a new price). The market moved to 788 gp; yours is at
		 * 791 gp. Re-list at 788 gp — aborting keeps whatever already filled.
		 * Right-click to stop being told to reprice it. Click to inspect it."
		 * Every clause true, and nobody reads a paragraph off a 32px square.
		 *
		 * Same wording as the in-game box (GeOfferGridOverlay.stateLine), on
		 * purpose: these two describe the same eight slots, and two surfaces
		 * that disagree about what to call a state are worse than either.
		 */
		private String describe(SlotInfo s)
		{
			if (s == null || s.state == SlotState.EMPTY)
			{
				return "Empty slot";
			}
			final StringBuilder sb = new StringBuilder("<html>");
			sb.append(s.itemName != null ? s.itemName : "item");
			sb.append("<br>").append(stateLine(s));
			if (s.quantityTotal > 0)
			{
				/* The percentage is the whole reason to hover: the raw pair
				   needs dividing in your head, which is exactly the work the
				   bar underneath exists to save.

				   Exact counts, NOT the abbreviated form used elsewhere.
				   35,999 of 36,000 abbreviates to "36K of 36K", which next to
				   a truthful "(99%)" reads as a contradiction and makes the
				   reader distrust both numbers. */
				sb.append("<br>").append(s.buy ? "Bought " : "Sold ")
					.append(String.format("%,d", Math.max(0, s.quantityFilled)))
					.append(" of ").append(String.format("%,d", s.quantityTotal))
					.append(" (").append(percentText(s.quantityFilled, s.quantityTotal)).append("%)");
				/* "Abort keeps it" rides with the number it is about, and
				   only when there is something to keep.

				   The long tooltip said "aborting keeps whatever already
				   filled" on every red slot. As boilerplate it was part of
				   what made the thing a paragraph — but the question it
				   answers is real and it is about money: being told to
				   re-list looks like being told to throw away a part-filled
				   offer, and someone who believes that will sit on a
				   mispriced one rather than risk it. */
				if (s.state == SlotState.ACTIVE_ADJUST && !s.adviceSkipped && s.quantityFilled > 0)
				{
					sb.append(" \u2014 abort keeps it");
				}
			}
			/*
			 * The gestures, on one line, last.
			 *
			 * These were two whole sentences — "Right-click to stop being
			 * told to reprice it. Click to inspect it." — repeated on all
			 * eight squares, and a good part of what made this a paragraph.
			 * But they are the only place either gesture is discoverable:
			 * nothing on a 32px square suggests it is clickable, and an
			 * affordance nobody finds may as well not exist.
			 *
			 * So: one short line, both gestures, and only the ones that
			 * actually do something on THIS slot. The right-click is left off
			 * a slot already opted out, because the state line above it
			 * already says how to undo that.
			 */
			final List<String> gestures = new ArrayList<>();
			if (inspectable())
			{
				gestures.add("click: inspect");
			}
			if (!s.adviceSkipped
				&& (s.state == SlotState.ACTIVE_OK || s.state == SlotState.ACTIVE_ADJUST))
			{
				gestures.add("right-click: price it yourself");
			}
			if (!gestures.isEmpty())
			{
				sb.append("<br>").append(String.join("  \u00b7  ", gestures));
			}
			return sb.append("</html>").toString();
		}

		/**
		 * The instruction, not the diagnosis. "Needs a new price" on its own
		 * leaves you to go and work out WHICH price, and somebody duly
		 * cancelled an offer, re-placed it at the same number, and asked what
		 * they had cancelled for.
		 *
		 * It says re-list rather than modify, because the Exchange cannot
		 * edit a live offer's price — abort and place again is the only
		 * sequence there is.
		 */
		private String stateLine(SlotInfo s)
		{
			if (s.adviceSkipped)
			{
				return "You are pricing this one \u2014 right-click to undo.";
			}
			if (s.state == SlotState.READY_COLLECT)
			{
				return "Ready to collect.";
			}
			if (s.state == SlotState.ACTIVE_ADJUST)
			{
				if (s.noMargin)
				{
					return "No margin left \u2014 take a new flip.";
				}
				if (s.targetPrice > 0)
				{
					final String verb = s.buy ? "Raise your bid to " : "Lower your ask to ";
					final StringBuilder sb = new StringBuilder(verb)
						.append(String.format("%,d", s.targetPrice)).append(" gp");
					if (s.offerPrice > 0)
					{
						sb.append(" (yours: ").append(String.format("%,d", s.offerPrice)).append(")");
					}
					return sb.toString();
				}
				return "Priced off the market \u2014 re-list.";
			}
			/* Green has only ever meant "not red", which is true and says
			   nothing — see GeOfferGridOverlay.stateLine for the report. */
			return "Priced fine \u2014 leave it.";
		}


		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			final Graphics2D g2 = (Graphics2D) g;
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			final int w = getWidth();
			final int h = getHeight();
			final SlotState state = info != null ? info.state : SlotState.EMPTY;

			// Outline: colourless when empty so free slots read as gaps.
			g2.setColor(state == SlotState.EMPTY ? EMPTY_BORDER : accent(info));
			g2.drawRect(0, 0, w - 1, h - BAR_H - 2);

			final int barY = h - BAR_H;
			g2.setColor(TRACK);
			g2.fillRect(0, barY, w, BAR_H);
			if (state != SlotState.EMPTY && info != null)
			{
				// A collected-ready offer is done by definition, whatever the
				// counter says — otherwise a cancelled part-fill would show a
				// half bar next to a "ready to collect" outline.
				final double pct = state == SlotState.READY_COLLECT ? 1.0
					: (info.quantityTotal > 0 ? Math.min(1.0, info.quantityFilled / (double) info.quantityTotal) : 0.0);
				/* The bar too, not just the outline. A cell is one colour, and
				   a muted outline round a green fill would read as two
				   statuses on one slot. */
				g2.setColor(accent(info));
				g2.fillRect(0, barY, (int) Math.round(w * pct), BAR_H);
			}
		}
	}

	/**
	 * The slot's colour, given everything known about it.
	 *
	 * Split from accent(SlotState) because "you are pricing this one
	 * yourself" is not a state — the offer is still perfectly active — but it
	 * does change the colour, and the in-game overlay has always shown that
	 * while the sidebar strip did not. Two surfaces describing the same slot
	 * and disagreeing.
	 */
	static Color accent(SlotInfo s)
	{
		final SlotState state = s != null ? s.state : SlotState.EMPTY;
		/* Only an offer still WORKING can be one you are pricing yourself.
		   The flag outlives the offer into ready-to-collect, and muting a
		   collectable slot would hide the one state that wants a click. The
		   in-game overlay never meets this case, because buildSlotViews drops
		   inactive offers before it gets there. */
		if (s != null && s.adviceSkipped
			&& (state == SlotState.ACTIVE_OK || state == SlotState.ACTIVE_ADJUST))
		{
			return MUTED_COLOR;
		}
		return accent(state);
	}

	private static Color accent(SlotState state)
	{
		switch (state)
		{
			case ACTIVE_OK: return OK_COLOR;
			case ACTIVE_ADJUST: return ADJUST_COLOR;
			case READY_COLLECT: return COLLECT_COLOR;
			case EMPTY:
			default: return EMPTY_BORDER;
		}
	}

	private static String label(SlotState state)
	{
		switch (state)
		{
			case ACTIVE_OK: return "priced fine";
			case ACTIVE_ADJUST: return "needs a new price";
			case READY_COLLECT: return "ready to collect";
			case EMPTY:
			default: return "empty";
		}
	}
}

package com.pocketge.tracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.util.QuantityFormatter;

/**
 * The last few closed flips, and a link to all of them on pocketge.com.
 *
 * The two halves do different jobs, which is why both exist. The rows answer
 * "did that actually book, and for how much?" — a question you ask in the
 * seconds after a sell fills, standing at the Exchange, where opening a
 * browser is not a reasonable answer. The link answers "how am I doing?" —
 * sorting, charting, gp per slot-hour, a ledger thousands of rows deep, none
 * of which fits in a 225px column.
 *
 * Deliberately NOT paginated. Page arrows and a "Page 1 of 1" counter are a
 * lot of furniture for a column this narrow, and paging is browsing, which is
 * the thing the link is for. This is the tail of the ledger, not a view onto
 * it, so it has a fixed small length and no controls.
 */
public class HistoryPanel extends JPanel
{
	/** How many recent flips get a row. Enough to cover a burst of fills
	 *  without the section growing past the watchlist beneath it. */
	private static final int RECENT = 5;

	private static final Color POSITIVE = new Color(0x1F, 0xB8, 0x5C);
	private static final Color NEGATIVE = new Color(0xEF, 0x53, 0x50);
	private static final Color ROW_TEXT = new Color(0xD9, 0xD3, 0xC7);

	public interface Actions
	{
		/** Routed through the plugin rather than opening a URL here, so every
		 *  chart in the sidebar reuses the same tab — see
		 *  AdvisorPanel.Actions.openChart. */
		void openChart(String itemName);
	}

	private final JLabel countLabel = new JLabel();
	private final JPanel rows = new JPanel();
	private final Actions actions;
	/** False between logout and the next login. Every flip here belongs to the
	 *  character that made it, and logged out there is no character — the same
	 *  reason the stats header blanks and the watchlist hides itself. A list of
	 *  somebody's trades sitting under "Log in to the game" is the panel
	 *  claiming to know whose they are when it does not. */
	private boolean loggedIn = true;
	/** The last list handed to {@link #update}, so logging back in can redraw
	 *  without waiting for the next refresh to come round. */
	private List<Flip> lastFlips = List.of();

	public HistoryPanel(Actions actions)
	{
		this.actions = actions;
		setLayout(new BorderLayout(0, 4));
		setOpaque(false);
		setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));

		JPanel header = new JPanel(new BorderLayout(0, 2));
		header.setOpaque(false);

		countLabel.setForeground(Brand.TEXT_STRUCTURAL);
		countLabel.setFont(countLabel.getFont().deriveFont(Font.BOLD, 11f));
		header.add(countLabel, BorderLayout.WEST);

		JLabel link = new JLabel("Flip history ↗", SwingConstants.RIGHT);
		link.setForeground(Brand.TEXT_STRUCTURAL);
		link.setFont(link.getFont().deriveFont(11f));
		link.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		/* Says what it needs, because the page cannot read your ledger over
		   the public internet and never will — it asks the plugin for it on
		   127.0.0.1. With the bridge off the page opens and explains that;
		   better to say so here, before the click. */
		link.setToolTipText("<html>Every flip you have ever made, on pocketge.com."
			+ "<br>Needs <b>Local website bridge</b> switched on in settings — the page"
			+ "<br>reads the ledger from this computer, not from a server.</html>");
		link.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				LinkBrowser.browse(PocketGeLinks.flips("flip_history"));
			}
		});
		header.add(link, BorderLayout.EAST);
		add(header, BorderLayout.NORTH);

		rows.setOpaque(false);
		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		add(rows, BorderLayout.CENTER);

		update(List.of());
	}

	/** Call on the Swing EDT when the player logs in or out. */
	public void setLoggedIn(boolean loggedIn)
	{
		if (this.loggedIn == loggedIn)
		{
			return;
		}
		this.loggedIn = loggedIn;
		update(lastFlips);
	}

	/** Call on the Swing EDT whenever the flip list changes. */
	public void update(List<Flip> flips)
	{
		lastFlips = flips != null ? flips : List.of();
		if (!loggedIn)
		{
			/* Rows gone, and no caption: the advisor's banner at the top of
			   the sidebar is the single place that explains a logged-out
			   panel. The link stays live — pocketge.com is a website and does
			   not need you logged into the game to show you your history. */
			countLabel.setText("");
			rows.removeAll();
			rows.revalidate();
			rows.repaint();
			return;
		}
		updateRows(lastFlips);
	}

	private void updateRows(List<Flip> flips)
	{
		/* One row per TRADE, not per fill. A sell offer is filled in as many
		   chunks as the Exchange finds buyers for, so one sale of 8,218
		   adamantite bars arrived here as five rows — "2 x Adamantite bar,
		   +22 gp" among them — which reports the shape of the order book
		   rather than what you did. The fills are still recorded and still
		   priced individually; they are only shown as the trade they were. */
		final List<Flip> trades = Flip.byTrade(flips);
		final int n = trades.size();
		countLabel.setText(n + (n == 1 ? " flip recorded" : " flips recorded"));

		rows.removeAll();
		/* Newest first. The tracker appends as flips close, so the tail of the
		   list is the part you have not seen yet. */
		for (int i = n - 1; i >= 0 && n - i <= RECENT; i--)
		{
			rows.add(row(trades.get(i)));
		}
		rows.revalidate();
		rows.repaint();
	}

	private JPanel row(Flip f)
	{
		final JPanel p = new JPanel(new BorderLayout(10, 0))
		{
			@Override
			public Dimension getPreferredSize()
			{
				/* Width 0, real height.
				 *
				 * BoxLayout takes its container's preferred width from the
				 * widest child, so "18,000 × Sapphire necklace" next to
				 * "-666K gp" asked for 243px inside a 217px column — which
				 * does not clip, it widens the sidebar's scroll content and
				 * puts a horizontal scrollbar under the whole panel. The row
				 * is stretched to the full column width by getMaximumSize
				 * below regardless, so it never needs to ask for any. */
				return new Dimension(0, super.getPreferredSize().height);
			}
		};
		p.setOpaque(false);
		p.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));
		p.setAlignmentX(0f);

		/* Abbreviated, unlike the quantity on the offer chip — that one you
		   type, this one you read. "18K ×" buys back about 25px of item name
		   in a column that has none to spare, and the exact figure is a hover
		   away. */
		final JLabel name = new JLabel(QuantityFormatter.quantityToStackSize(f.quantity)
			+ " × " + f.itemName);
		name.setForeground(ROW_TEXT);
		name.setFont(name.getFont().deriveFont(11f));

		final JLabel amount = new JLabel(signed(f.profit), SwingConstants.RIGHT);
		amount.setForeground(f.profit >= 0 ? POSITIVE : NEGATIVE);
		amount.setFont(amount.getFont().deriveFont(Font.BOLD, 11f));

		/* Name in CENTER and money in EAST, so a long item name ellipsizes
		   and the figure beside it never does — same priority as the stat
		   rows. The tooltip carries the full name either way. */
		p.add(name, BorderLayout.CENTER);
		p.add(amount, BorderLayout.EAST);

		final String tip = tooltip(f);
		name.setToolTipText(tip);
		amount.setToolTipText(tip);
		p.setToolTipText(tip);

		p.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		p.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (actions != null)
				{
					actions.openChart(f.itemName);
				}
			}
		});
		/* BoxLayout hands a component its MAXIMUM height, and a BorderLayout
		   panel's is unbounded — without this one row would swallow the
		   section. Width stays unbounded so the row still fills the column. */
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, p.getPreferredSize().height));
		return p;
	}

	private static String tooltip(Flip f)
	{
		final StringBuilder sb = new StringBuilder("<html>");
		sb.append(f.itemName).append("<br>")
			.append("Bought ").append(String.format("%,d", f.quantity))
			.append(" at ").append(QuantityFormatter.quantityToStackSize(f.avgBuy())).append(" gp<br>")
			.append("Sold at ").append(QuantityFormatter.quantityToStackSize(f.avgSell())).append(" gp<br>")
			.append("Tax ").append(QuantityFormatter.quantityToStackSize(f.tax)).append(" gp<br>")
			.append("Profit ").append(signed(f.profit)).append("<br>");
		final long held = f.holdMillis();
		if (held < 0)
		{
			/* Never "0:00:00". The plugin did not watch this stack being
			   bought, so it does not know — and an instant fill is the most
			   flattering thing a blank could be mistaken for. */
			sb.append("Held — (buy time not recorded)");
		}
		else
		{
			sb.append("Held ").append(StatsHeaderPanel.formatDuration(held));
			final long perHour = f.profitPerHour();
			if (perHour != 0)
			{
				sb.append(" · ").append(signed(perHour)).append("/hr");
			}
		}
		sb.append("<br><br>Click for the chart on pocketge.com");
		return sb.toString();
	}

	private static String signed(long v)
	{
		return (v >= 0 ? "+" : "") + QuantityFormatter.quantityToStackSize(v) + " gp";
	}
}

package com.pocketge.tracker;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.SynchronousQueue;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

/**
 * Tiny opt-in HTTP listener bound to 127.0.0.1 ONLY. pocketge.com open in
 * the local browser polls GET /flips to show this session's trades, your
 * plugin-side Favorite lists, portfolio value, and current top
 * recommendation — a same-machine link between the plugin and the site with
 * no accounts and no server: data never leaves the machine. It also accepts
 * POST /favorites (add/remove an item) and POST /favoriteLists
 * (create/rename/delete a list) so the site can drive the same TradingView-
 * style watchlists the in-game panel manages — the link works both
 * directions, not just plugin -> website. CORS is restricted to the
 * PocketGE origins, and the Private-Network-Access preflight header is
 * answered so Chromium allows the https page -> localhost fetch.
 */
public class LocalBridgeServer
{
	private static final String[] ALLOWED_ORIGINS = {
		"https://pocketge.com",
		"https://www.pocketge.com",
		"http://localhost:8901" // local dev of the site
	};

	/** Called with (listId, itemId, name, remove) when the website POSTs a
	 *  favorite change — remove=true means unfavorite rather than add.
	 *  listId is null when the website didn't specify one, meaning
	 *  "whichever list is currently active in-game". */
	public interface FavoriteWriter
	{
		void write(String listId, int itemId, String name, boolean remove);
	}

	/** Called when the website POSTs a list-management action. create()
	 *  returns the new list's id (never null/blank name is rejected before
	 *  this is called). rename()/delete() are no-ops if listId doesn't match
	 *  any current list — same as the in-game chip menu's own guards. */
	public interface ListWriter
	{
		String create(String name);
		void rename(String listId, String name);
		void delete(String listId);
		/** Two-way order sync: the site sends the order it is showing and the
		 *  plugin's list is rewritten to match. Membership is never changed
		 *  by this — see FavoriteLists.reorderTo for why that has to be true
		 *  when both ends can edit at once. */
		void reorder(String listId, List<Integer> itemIds);
	}

	/**
	 * "Show this item" pushed from the plugin to a PocketGE tab that is
	 * already open, instead of launching a browser.
	 *
	 * Opening a new tab per chart click is the wrong default when the site
	 * is already up: depending on the desktop's URL handler it can land on
	 * whatever tab happens to be focused, which in practice means it takes
	 * over something else you were watching. If a tab is already polling us
	 * it can just navigate itself.
	 *
	 * {@code seq} is monotonic for the plugin's lifetime, so a poller can
	 * tell a NEW request from one it already acted on by remembering the
	 * last seq it handled — polling is at-least-once and the same payload
	 * will be seen repeatedly.
	 */
	public static class NavRequest
	{
		public final long seq;
		public final String query;
		public final int itemId;
		public final long at;

		public NavRequest(long seq, String query, int itemId, long at)
		{
			this.seq = seq;
			this.query = query;
			this.itemId = itemId;
			this.at = at;
		}
	}

	/* Injected from the client via the plugin — the hub's verification
	   (correctly) rejects fresh Gson instances. */
	private final Gson gson;
	private HttpServer server;
	/** When a PocketGE page last polled us, epoch millis, 0 for never.
	   Only same-origin-allowed GETs count, so a stray curl can't make the
	   plugin believe a tab is open. Written on the bridge's HTTP threads,
	   read from the client thread — hence volatile. */
	private volatile long lastPollAt;

	/** How many requests the bridge will serve at once. Eight covers the
	 *  ordinary traffic (one /flips poll, the odd write) plus a long-poll
	 *  from each of a few tabs, with room to spare on a loopback server that
	 *  never sees real concurrency. */
	private static final int BRIDGE_THREADS = 8;
	/** How long a /nav request parks before answering "nothing yet". Short
	 *  enough to stay inside every proxy and browser idle timeout, long
	 *  enough that the reconnect cost is negligible. */
	private static final long NAV_WAIT_MS = 25_000;
	private ThreadPoolExecutor navExecutor;
	/** The most recent "show this item" request, or null. Guarded by
	 *  {@link #navLock}, which is also what a parked /nav waits on. */
	private NavRequest nav;
	private final Object navLock = new Object();
	/** Set on stop() so parked requests return instead of waiting out their
	 *  full 25 seconds while the plugin is trying to shut down. */
	private volatile boolean stopping;
	/** How many /nav requests are parked right now. */
	private final AtomicInteger parkedNavs = new AtomicInteger();
	/**
	 * Never park more than this many at once — deliberately below
	 * BRIDGE_THREADS.
	 *
	 * The pool rejects with CallerRunsPolicy, and the caller here is the
	 * HttpServer's own dispatcher thread. So a saturated pool would hand a
	 * 25-second park straight to the thread that accepts connections, stalling
	 * every endpoint — precisely the failure the pool was introduced to
	 * prevent, just reached from the other side. Capping the parkers below the
	 * pool size means the pool can never saturate on long-polls, so that
	 * hand-off cannot happen.
	 *
	 * Past the cap a /nav is answered immediately instead of waiting, and the
	 * page falls back to its ordinary 5-second poll.
	 */
	private static final int MAX_PARKED_NAVS = 4;

	/**
	 * Hand the bridge a chart click to deliver.
	 *
	 * Wakes every parked /nav immediately, which is the entire point: the
	 * site used to learn about this on its next 5-second poll, and a hidden
	 * background tab's timers are throttled well past that. A request that is
	 * already open is not a timer, so it is answered the moment this is
	 * called.
	 */
	public void publishNav(NavRequest request)
	{
		synchronized (navLock)
		{
			nav = request;
			navLock.notifyAll();
		}
	}

	public LocalBridgeServer(Gson gson)
	{
		this.gson = gson;
	}

	public void start(int port, Supplier<Map<String, Object>> payload, Supplier<Map<String, Object>> history,
		FavoriteWriter favoriteWriter, ListWriter listWriter) throws IOException
	{
		stop();
		server = HttpServer.create(new InetSocketAddress(InetAddress.getLoopbackAddress(), port), 0);
		server.createContext("/flips", ex -> handleGet(ex, payload));
		/* Separate from /flips on purpose. /flips is polled every few seconds
		 * forever and carries the recent window; this is the entire ledger,
		 * which is years of trades and megabytes of JSON, and is fetched only
		 * when someone opens the history page. Serving it on the poll would
		 * mean re-serializing the whole history several times a minute to
		 * render eight rows. `flipCount` in /flips is how the page knows when
		 * to come back here. */
		server.createContext("/history", ex -> handleGet(ex, history));
		server.createContext("/status", ex -> handleGet(ex, () -> {
			Map<String, Object> m = new HashMap<>();
			m.put("ok", true);
			m.put("plugin", "pocketge-flip-tracker");
			return m;
		}));
		server.createContext("/favorites", ex -> handleFavoritePost(ex, favoriteWriter));
		server.createContext("/favoriteLists", ex -> handleFavoriteListsPost(ex, listWriter));
		server.createContext("/nav", this::handleNavLongPoll);
		/* A REAL pool, not setExecutor(null).
		 *
		 * The default runs every handler on the single thread start() created,
		 * which was fine while every response was immediate — and is fatal now
		 * that /nav parks for up to 25 seconds waiting for a chart click. On
		 * the default executor one parked request would stall /flips, the
		 * favourites writes and the list reorders behind it.
		 *
		 * Capped, because these threads are only ever unblocked by a person
		 * clicking a chart button or a timeout: an unbounded pool would let a
		 * page with a reconnect bug quietly accumulate them. Past the cap a
		 * long-poll is answered immediately instead of queueing, so the site
		 * falls back to its ordinary 5-second poll rather than hanging.
		 *
		 * Daemon threads: this lives inside the RuneLite client and must never
		 * be the reason the JVM stays up. */
		navExecutor = new ThreadPoolExecutor(0, BRIDGE_THREADS, 30L, TimeUnit.SECONDS,
			new SynchronousQueue<>(), r ->
			{
				final Thread t = new Thread(r, "pocketge-bridge");
				t.setDaemon(true);
				return t;
			}, new ThreadPoolExecutor.CallerRunsPolicy());
		server.setExecutor(navExecutor);
		server.start();
	}

	private void handleGet(HttpExchange ex, Supplier<Map<String, Object>> payload) throws IOException
	{
		if (corsPreflight(ex, "GET, OPTIONS"))
		{
			return;
		}
		if (isAllowedOrigin(ex.getRequestHeaders().getFirst("Origin")))
		{
			lastPollAt = System.currentTimeMillis();
		}
		byte[] body = gson.toJson(payload.get()).getBytes(StandardCharsets.UTF_8);
		ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
		ex.sendResponseHeaders(200, body.length);
		try (OutputStream os = ex.getResponseBody())
		{
			os.write(body);
		}
	}

	/**
	 * GET /nav?since=N — "tell me the moment a chart is clicked in game".
	 *
	 * Parks until there is a NavRequest newer than {@code since}, or for
	 * {@link #NAV_WAIT_MS}, whichever comes first, then answers
	 * {"navRequest": …} or {"navRequest": null}. The page reconnects
	 * immediately either way.
	 *
	 * Why not just poll faster: the browser tab is behind the game, and a
	 * hidden tab's setInterval is throttled — to once a second at best, and
	 * to once a MINUTE once Chrome's intensive throttling kicks in. Shortening
	 * the interval cannot fix something the browser is deliberately slowing
	 * down. An already-open request is not a timer, so its response is
	 * delivered on the network task source and arrives promptly regardless.
	 *
	 * {@code since} of 0 (or absent) answers with whatever is current, which
	 * is how a freshly loaded page learns the seq it should dedupe from.
	 */
	private void handleNavLongPoll(HttpExchange ex) throws IOException
	{
		if (corsPreflight(ex, "GET, OPTIONS"))
		{
			return;
		}
		final boolean allowed = isAllowedOrigin(ex.getRequestHeaders().getFirst("Origin"));
		if (allowed)
		{
			// A parked long-poll is still a tab being open — in fact it is
			// better evidence than a 5s tick, since it is continuous.
			lastPollAt = System.currentTimeMillis();
		}
		long since = 0;
		try
		{
			final String query = ex.getRequestURI().getQuery();
			if (query != null)
			{
				for (String part : query.split("&"))
				{
					if (part.startsWith("since="))
					{
						since = Long.parseLong(part.substring(6));
					}
				}
			}
		}
		catch (RuntimeException ignore)
		{
			since = 0; // unparseable: treat as "tell me what's current"
		}

		NavRequest found = null;
		final long deadline = System.currentTimeMillis() + NAV_WAIT_MS;
		final boolean mayPark = parkedNavs.incrementAndGet() <= MAX_PARKED_NAVS;
		try
		{
		synchronized (navLock)
		{
			while (!stopping)
			{
				if (nav != null && nav.seq > since)
				{
					found = nav;
					break;
				}
				if (!mayPark)
				{
					// Too many already waiting — see MAX_PARKED_NAVS. Answer
					// with what we have rather than holding another thread.
					break;
				}
				final long remaining = deadline - System.currentTimeMillis();
				if (remaining <= 0)
				{
					break;
				}
				try
				{
					navLock.wait(remaining);
				}
				catch (InterruptedException e)
				{
					/* Stop waiting and answer with whatever we have. The
					   interrupt flag is deliberately NOT re-asserted: nothing
					   below this runs long enough to need to observe it — the
					   handler writes one small JSON body and returns — and the
					   plugin hub does not permit a plugin to interrupt threads
					   at all, which includes handing the flag back. */
					break;
				}
			}
		}
		}
		finally
		{
			parkedNavs.decrementAndGet();
		}
		// Keep polling alive as evidence of a tab even across a long park.
		if (allowed)
		{
			lastPollAt = System.currentTimeMillis();
		}
		final Map<String, Object> body = new HashMap<>();
		body.put("navRequest", found);
		respondJson(ex, body);
	}

	private void respondJson(HttpExchange ex, Map<String, Object> body) throws IOException
	{
		final byte[] bytes = gson.toJson(body).getBytes(StandardCharsets.UTF_8);
		ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
		ex.sendResponseHeaders(200, bytes.length);
		try (OutputStream os = ex.getResponseBody())
		{
			os.write(bytes);
		}
	}

	/** POST { "id": 123, "name": "Diamond", "remove": false, "listId": "…" }
	 *  — adds (or removes) a favorite the same way the in-game star button
	 *  does. listId is optional: omit it to target whichever list is
	 *  currently active in-game. A malformed body is answered with 400
	 *  rather than silently ignored, so a website-side bug is visible
	 *  instead of just "didn't sync". */
	private void handleFavoritePost(HttpExchange ex, FavoriteWriter favoriteWriter) throws IOException
	{
		if (corsPreflight(ex, "GET, POST, OPTIONS"))
		{
			return;
		}
		if (!"POST".equalsIgnoreCase(ex.getRequestMethod()))
		{
			ex.sendResponseHeaders(405, -1);
			ex.close();
			return;
		}
		try
		{
			final JsonObject o = readJsonBody(ex);
			final int id = o.get("id").getAsInt();
			final String name = o.has("name") && !o.get("name").isJsonNull() ? o.get("name").getAsString() : ("Item " + id);
			final boolean remove = o.has("remove") && o.get("remove").getAsBoolean();
			final String listId = o.has("listId") && !o.get("listId").isJsonNull() ? o.get("listId").getAsString() : null;
			favoriteWriter.write(listId, id, name, remove);
			respondOk(ex);
		}
		catch (Exception e)
		{
			ex.sendResponseHeaders(400, -1);
			ex.close();
		}
	}

	/** POST { "action": "create"|"rename"|"delete"|"reorder", "listId": "…",
	 *  "name": "…", "itemIds": [1601, 561, …] }
	 *  — drives the same list chip-menu actions (new list / rename / delete)
	 *  the in-game panel offers, from the website. "create" only needs
	 *  name; "rename" needs both; "delete" only needs listId. Responds with
	 *  { "ok": true, "listId": "…" } — for "create" that's the new list's id,
	 *  so the site can switch straight to it without a round trip. */
	private void handleFavoriteListsPost(HttpExchange ex, ListWriter listWriter) throws IOException
	{
		if (corsPreflight(ex, "GET, POST, OPTIONS"))
		{
			return;
		}
		if (!"POST".equalsIgnoreCase(ex.getRequestMethod()))
		{
			ex.sendResponseHeaders(405, -1);
			ex.close();
			return;
		}
		try
		{
			final JsonObject o = readJsonBody(ex);
			final String action = o.get("action").getAsString();
			String resultListId = null;
			switch (action)
			{
				case "create":
				{
					final String name = o.get("name").getAsString();
					if (name == null || name.trim().isEmpty())
					{
						throw new IllegalArgumentException("blank list name");
					}
					resultListId = listWriter.create(name.trim());
					break;
				}
				case "rename":
				{
					final String name = o.get("name").getAsString();
					if (name == null || name.trim().isEmpty())
					{
						throw new IllegalArgumentException("blank list name");
					}
					listWriter.rename(o.get("listId").getAsString(), name.trim());
					break;
				}
				case "delete":
					listWriter.delete(o.get("listId").getAsString());
					break;
				case "reorder":
				{
					final com.google.gson.JsonArray arr = o.getAsJsonArray("itemIds");
					final List<Integer> ids = new java.util.ArrayList<>();
					for (int i = 0; i < arr.size(); i++)
					{
						ids.add(arr.get(i).getAsInt());
					}
					if (ids.isEmpty())
					{
						throw new IllegalArgumentException("empty itemIds");
					}
					listWriter.reorder(o.has("listId") && !o.get("listId").isJsonNull()
						? o.get("listId").getAsString() : null, ids);
					break;
				}
				default:
					throw new IllegalArgumentException("unknown action: " + action);
			}
			ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
			final JsonObject resp = new JsonObject();
			resp.addProperty("ok", true);
			if (resultListId != null)
			{
				resp.addProperty("listId", resultListId);
			}
			final byte[] body = gson.toJson(resp).getBytes(StandardCharsets.UTF_8);
			ex.sendResponseHeaders(200, body.length);
			try (OutputStream os = ex.getResponseBody())
			{
				os.write(body);
			}
		}
		catch (Exception e)
		{
			ex.sendResponseHeaders(400, -1);
			ex.close();
		}
	}

	private JsonObject readJsonBody(HttpExchange ex) throws IOException
	{
		final ByteArrayOutputStream buf = new ByteArrayOutputStream();
		try (InputStream is = ex.getRequestBody())
		{
			is.transferTo(buf);
		}
		return gson.fromJson(buf.toString(StandardCharsets.UTF_8), JsonObject.class);
	}

	private void respondOk(HttpExchange ex) throws IOException
	{
		ex.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
		final byte[] body = "{\"ok\":true}".getBytes(StandardCharsets.UTF_8);
		ex.sendResponseHeaders(200, body.length);
		try (OutputStream os = ex.getResponseBody())
		{
			os.write(body);
		}
	}

	/** Shared Origin-check + preflight handling. Returns true if the
	 *  exchange was fully handled here (an OPTIONS preflight) and the
	 *  caller should stop. */
	private static boolean isAllowedOrigin(String origin)
	{
		if (origin == null)
		{
			return false;
		}
		for (String o : ALLOWED_ORIGINS)
		{
			if (o.equals(origin))
			{
				return true;
			}
		}
		return false;
	}

	private boolean corsPreflight(HttpExchange ex, String allowedMethods) throws IOException
	{
		String origin = ex.getRequestHeaders().getFirst("Origin");
		String allow = isAllowedOrigin(origin) ? origin : null;
		if (allow != null)
		{
			ex.getResponseHeaders().set("Access-Control-Allow-Origin", allow);
			ex.getResponseHeaders().set("Vary", "Origin");
		}
		if ("OPTIONS".equalsIgnoreCase(ex.getRequestMethod()))
		{
			ex.getResponseHeaders().set("Access-Control-Allow-Methods", allowedMethods);
			ex.getResponseHeaders().set("Access-Control-Allow-Headers", "*");
			/* Chromium Private Network Access: an https page fetching a
			   private address must be explicitly allowed. */
			ex.getResponseHeaders().set("Access-Control-Allow-Private-Network", "true");
			ex.sendResponseHeaders(204, -1);
			ex.close();
			return true;
		}
		return false;
	}

	/** Epoch millis of the last poll from a PocketGE page, 0 for never. */
	public long lastPollAt()
	{
		return lastPollAt;
	}

	/** Best available answer to "is a PocketGE tab open right now". It is a
	 *  proxy, not a fact: the page polls on a timer, so this stays true for
	 *  up to one poll interval after the tab is closed. Callers must degrade
	 *  gracefully when a handoff turns out to have no one listening. */
	public boolean hasRecentClient(long withinMs)
	{
		final long seen = lastPollAt;
		return seen > 0 && System.currentTimeMillis() - seen <= withinMs;
	}

	/**
	 * Whether a page is parked on /nav RIGHT NOW, waiting to be handed an
	 * item.
	 *
	 * Much stronger evidence of a usable tab than {@link #hasRecentClient}:
	 * that one says a page polled at some point in the last N seconds, which
	 * stays true for a tab closed moments ago and for one the browser has
	 * since frozen in the background. A parked request is a live connection —
	 * if it is there, publishNav reaches something.
	 */
	public boolean hasParkedNavListener()
	{
		return parkedNavs.get() > 0;
	}

	public void stop()
	{
		/* Wake the parked long-polls FIRST. server.stop(0) waits for handlers
		   to finish, and a /nav sitting on a 25-second timer would hold the
		   plugin's shutdown for as long as it had left to run. */
		stopping = true;
		synchronized (navLock)
		{
			navLock.notifyAll();
		}
		if (server != null)
		{
			server.stop(0);
			server = null;
		}
		if (navExecutor != null)
		{
			/* shutdown(), never shutdownNow(): the latter interrupts the pool's
			   threads, which a hub plugin may not do. It is also unnecessary
			   here — the notifyAll above, paired with the stopping flag the
			   wait loop tests, has already released every parked request, so
			   there is nothing left to interrupt. shutdown() does not block. */
			navExecutor.shutdown();
			navExecutor = null;
		}
		// Re-arm: start() can be called again when the setting is toggled back on.
		stopping = false;
		nav = null;
	}

	/**
	 * One stack sitting in the bank, priced. The bridge used to publish a
	 * single portfolioValue total, so the website could show what you were
	 * worth but never what you were HOLDING — which is the half you act on.
	 * Cash is excluded (it arrives as its own `cash` field); an unpriced item
	 * carries value 0 rather than being dropped, so the composition stays
	 * honest about what it couldn't value.
	 */
	public static class BankStack
	{
		public final int id;
		public final String name;
		public final int quantity;
		public final long value; // quantity x current insta-sell, 0 if unpriced

		public BankStack(int id, String name, int quantity, long value)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
			this.value = value;
		}
	}

	/** Build the /flips payload from tracker + panel state. Static so the
	 *  plugin can also reuse it for future export features.
	 *  {@code favoriteLists} / {@code topRecommendation} are whatever was
	 *  most recently loaded/rendered — null/empty degrades cleanly, matching
	 *  how the website already treats "advisor off" or "no favorites yet".
	 *  favoriteLists carries every list's raw id/name/color/items (not
	 *  resolved prices — the website already fetches live prices itself and
	 *  only needs to know which items belong to which list). */
	public static Map<String, Object> payload(long sessionProfit, long lifetimeProfit, List<Flip> flips, List<TradeFill> fills,
		long portfolioValue, boolean bankSeen, long bankSeenAt, long cash, List<BankStack> bankStacks,
		List<FavoriteLists.FavoriteList> favoriteLists, String activeFavoriteListId, Advisor.Suggestion topRecommendation)
	{
		Map<String, Object> m = new HashMap<>();
		m.put("sessionProfit", sessionProfit);
		m.put("lifetimeProfit", lifetimeProfit);
		m.put("flips", flips);
		m.put("fills", fills);
		m.put("portfolioValue", portfolioValue);
		/* False until the player has opened their bank at least once this
		   session — RuneLite can't read bank contents any other way, so
		   portfolioValue silently excludes it until then. The website uses
		   this to say so instead of just showing a too-low total.
		   bankSeenAt (epoch millis, 0 for never) says HOW STALE that snapshot
		   is: "seen" alone can't distinguish a bank read ten seconds ago from
		   one read three hours and forty trades ago, and the site was
		   presenting both as equally current. */
		m.put("bankSeen", bankSeen);
		m.put("bankSeenAt", bankSeenAt);
		m.put("cash", cash);
		m.put("bankStacks", bankStacks);
		m.put("favoriteLists", favoriteLists);
		m.put("activeFavoriteListId", activeFavoriteListId);
		m.put("topRecommendation", topRecommendation);
		m.put("generatedAt", System.currentTimeMillis());
		return m;
	}
}

