	/** Restarts the client: snapshot out of one tracker, into a fresh one,
	 *  exactly as the plugin does across a session. */
	private static FlipTracker restart(FlipTracker t)
	{
		FlipTracker next = new FlipTracker();
		next.restore(t.snapshot());
		return next;
	}

	/**
	 * The whole point of persisting slot baselines: offers keep filling while
	 * you are logged out, and the fills that happen then used to be thrown
	 * away. A slot the tracker remembers is a slot it can measure against.
	 */
	@Test
	public void fillsThatHappenWhileLoggedOutAreCounted()
	{
		FlipTracker t = new FlipTracker();
		t.setAccountHash(4242L);
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 1_000, false);   // placed
		t.onOffer(2L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 1_000, false);

		// ... log out, close the client, come back tomorrow: the same offer
		// has filled another 400.
		FlipTracker t2 = restart(t);
		t2.setAccountHash(4242L);
		TradeFill f = t2.onOffer(99L, 0, 1601, "Diamond", true, 500, 900_000L, 1_800L, 1_000, false);

		Assert.assertNotNull("the overnight fill has to count", f);
		Assert.assertEquals(400, f.quantity);
		Assert.assertEquals(720_000L, f.spent);
		Assert.assertEquals(500L, t2.getOpenBuyTotals().get(1601)[0]);
		Assert.assertEquals(900_000L, t2.getOpenBuyTotals().get(1601)[1]);
	}

	/**
	 * That lot's cost is exact but its clock is not: nobody watched it fill.
	 * A flip closed against it reports an unknown hold rather than one
	 * measured from the moment the client happened to reopen.
	 */
	@Test
	public void anOfflineFillHasNoKnownBuyTime()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 100, false);
		FlipTracker t2 = restart(t);
		t2.onOffer(1_000L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 100, false);
		t2.onOffer(2_000L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 100, true);

		t2.onOffer(3_000L, 1, 1601, "Diamond", false, 0, 0L, 2_000L, 100, false);
		t2.onOffer(4_000L + 7_200_000L, 1, 1601, "Diamond", false, 100, 200_000L, 2_000L, 100, false);

		List<Flip> flips = t2.getFlips();
		Assert.assertEquals(1, flips.size());
		Assert.assertEquals("cost is known exactly", 180_000L, flips.get(0).buySpent);
		Assert.assertEquals("when it was bought is not", -1L, flips.get(0).holdMillis());
	}

	/** A live fill still carries its real time — the unknown above is for
	 *  offline growth only, not for every restored slot forever. */
	@Test
	public void theSlotGoesBackToLiveTimingAfterOneEvent()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 200, false);
		FlipTracker t2 = restart(t);
		t2.onOffer(1_000L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 200, false); // offline
		t2.onOffer(5_000L, 0, 1601, "Diamond", true, 200, 360_000L, 1_800L, 200, false); // live
		t2.onOffer(6_000L, 0, 1601, "Diamond", true, 200, 360_000L, 1_800L, 200, true);

		t2.onOffer(7_000L, 1, 1601, "Diamond", false, 0, 0L, 2_000L, 200, false);
		// Sell only the second lot's worth, so FIFO reaches the live one after
		// the offline one is consumed.
		t2.onOffer(8_000L, 1, 1601, "Diamond", false, 100, 200_000L, 2_000L, 200, false);
		t2.onOffer(5_000L + 3_600_000L, 1, 1601, "Diamond", false, 200, 400_000L, 2_000L, 200, false);

		List<Flip> flips = t2.getFlips();
		Assert.assertEquals(2, flips.size());
		Assert.assertEquals("offline lot", -1L, flips.get(0).holdMillis());
		Assert.assertEquals("live lot", 3_600_000L, flips.get(1).holdMillis());
	}

	/**
	 * A slot holding a DIFFERENT offer than the one remembered must baseline,
	 * not book. Same item and direction is not enough — you can abort a buy
	 * and place another for the same thing at a different price, and measuring
	 * the new one against the old one's numbers invents a fill.
	 */
	@Test
	public void aReplacedOfferIsNotTheRememberedOne()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 1_000, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 300, 540_000L, 1_800L, 1_000, false);

		// Same item, same direction, but re-listed 100 gp higher.
		FlipTracker t2 = restart(t);
		TradeFill f = t2.onOffer(99L, 0, 1601, "Diamond", true, 400, 760_000L, 1_900L, 1_000, false);
		Assert.assertNull("different price, so a different offer", f);

		// And a different size is equally a different offer.
		FlipTracker t3 = restart(t);
		Assert.assertNull(t3.onOffer(99L, 0, 1601, "Diamond", true, 400, 720_000L, 1_800L, 5_000, false));

		// A slot that went BACKWARDS was emptied and refilled unseen.
		FlipTracker t4 = restart(t);
		Assert.assertNull(t4.onOffer(99L, 0, 1601, "Diamond", true, 50, 90_000L, 1_800L, 1_000, false));
	}

	/**
	 * Slot 3 is a different offer on every character, and this state file is
	 * shared by all of them, so baselines do not survive a change of account.
	 */
	@Test
	public void baselinesDoNotCrossAccounts()
	{
		FlipTracker t = new FlipTracker();
		t.setAccountHash(1111L);
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 1_000, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 300, 540_000L, 1_800L, 1_000, false);

		/* On the alt, slot 0 is an offer we have never seen, so it seeds: the
		   fill is the whole 700 the offer itself reports. The number that
		   would mean the baselines HAD crossed is 400 — a delta measured
		   against the main's 300. */
		FlipTracker t2 = restart(t);
		t2.setAccountHash(2222L);
		TradeFill alt = t2.onOffer(99L, 0, 1601, "Diamond", true, 700, 1_260_000L, 1_800L, 1_000, false);
		Assert.assertNotNull(alt);
		Assert.assertEquals("seeded from zero, not measured off the main's baseline", 700, alt.quantity);

		// And on the main, the same event is growth on a known offer.
		FlipTracker t3 = restart(t);
		t3.setAccountHash(1111L);
		TradeFill main = t3.onOffer(99L, 0, 1601, "Diamond", true, 700, 1_260_000L, 1_800L, 1_000, false);
		Assert.assertNotNull(main);
		Assert.assertEquals(400, main.quantity);
	}

	/**
	 * Placing and collecting an offer produce no fill, but they DO move a
	 * baseline — and an unsaved baseline is re-taken from scratch next start,
	 * which is the bug this all exists to fix.
	 */
	@Test
	public void baselineOnlyChangesStillAskToBeSaved()
	{
		FlipTracker t = new FlipTracker();
		t.takeSlotsDirty();
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 100, false);
		Assert.assertTrue("placing an offer moved a baseline", t.takeSlotsDirty());
		Assert.assertFalse("and the flag clears when read", t.takeSlotsDirty());

		t.onOffer(2L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 100, true);
		Assert.assertTrue("collecting it moved a baseline too", t.takeSlotsDirty());
	}

	/**
	 * The receipt is on the offer. An offer met for the first time already
	 * part-filled carries the exact units and the exact gold in quantitySold
	 * and spent, and that used to be discarded — the plugin would tell you it
	 * had no idea what a stack cost while the client was still holding the
	 * proof.
	 */
	@Test
	public void aFirstSightingBooksWhatTheOfferAlreadyBought()
	{
		FlipTracker t = new FlipTracker();
		t.setAccountHash(7L);
		// Plugin enabled on top of a buy that is already 14,000 in.
		TradeFill f = t.onOffer(1L, 0, 1601, "Diamond", true, 14_000, 7_238_000L, 517L, 18_000, false);

		Assert.assertNotNull("the offer knew; the tracker should too", f);
		Assert.assertEquals(14_000, f.quantity);
		Assert.assertEquals(7_238_000L, f.spent);
		Assert.assertEquals(14_000L, t.getOpenBuyTotals().get(1601)[0]);
		Assert.assertEquals(7_238_000L, t.getOpenBuyTotals().get(1601)[1]);
	}

	/** Seeded only once. Relogging re-reports the same offer every time, and
	 *  the persisted baseline is what stops each of those looking new. */
	@Test
	public void aSeededOfferIsNotSeededAgainOnEveryLogin()
	{
		FlipTracker t = new FlipTracker();
		t.setAccountHash(7L);
		t.onOffer(1L, 0, 1601, "Diamond", true, 14_000, 7_238_000L, 517L, 18_000, false);

		for (int login = 0; login < 3; login++)
		{
			t = restart(t);
			t.setAccountHash(7L);
			Assert.assertNull("nothing new happened",
				t.onOffer(2L, 0, 1601, "Diamond", true, 14_000, 7_238_000L, 517L, 18_000, false));
		}
		Assert.assertEquals(14_000L, t.getOpenBuyTotals().get(1601)[0]);
		Assert.assertEquals(7_238_000L, t.getOpenBuyTotals().get(1601)[1]);
	}

	/** And not re-seeded by hopping between characters, which is why the
	 *  baselines are kept per account rather than wiped on a switch. */
	@Test
	public void switchingCharactersDoesNotReseed()
	{
		FlipTracker t = new FlipTracker();
		t.setAccountHash(1111L);
		t.onOffer(1L, 0, 1601, "Diamond", true, 14_000, 7_238_000L, 517L, 18_000, false);

		// Over to the alt, which has its own unrelated offer in slot 0...
		t = restart(t);
		t.setAccountHash(2222L);
		Assert.assertNotNull(t.onOffer(2L, 0, 561, "Nature rune", true, 5_000, 500_000L, 100L, 10_000, false));

		// ...and back. The main's slot 0 is remembered, so nothing re-books.
		t = restart(t);
		t.setAccountHash(1111L);
		Assert.assertNull("already counted under this character",
			t.onOffer(3L, 0, 1601, "Diamond", true, 14_000, 7_238_000L, 517L, 18_000, false));
		Assert.assertEquals(14_000L, t.getOpenBuyTotals().get(1601)[0]);
		Assert.assertEquals(5_000L, t.getOpenBuyTotals().get(561)[0]);
	}

	/** A seeded lot's gold is exact and its clock is not, same as an offline
	 *  one — nobody watched any of it fill. */
	@Test
	public void aSeededLotHasNoKnownBuyTime()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 100, false); // seeded
		t.onOffer(2L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 100, true);
		t.onOffer(3L, 1, 1601, "Diamond", false, 0, 0L, 2_000L, 100, false);
		t.onOffer(3L + 7_200_000L, 1, 1601, "Diamond", false, 100, 200_000L, 2_000L, 100, false);

		List<Flip> flips = t.getFlips();
		Assert.assertEquals(1, flips.size());
		Assert.assertEquals(180_000L, flips.get(0).buySpent);
		Assert.assertEquals(-1L, flips.get(0).holdMillis());
	}

	/** A brand-new offer is watched from zero, so its fills are witnessed and
	 *  keep their real times — seeding must not swallow those into "unknown". */
	@Test
	public void aBrandNewOfferStillTimesItsOwnFills()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1_000L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 100, false); // placed, empty
		t.onOffer(2_000L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 100, false);
		t.onOffer(2_500L, 0, 1601, "Diamond", true, 100, 180_000L, 1_800L, 100, true);
		t.onOffer(3_000L, 1, 1601, "Diamond", false, 0, 0L, 2_000L, 100, false);
		t.onOffer(2_000L + 3_600_000L, 1, 1601, "Diamond", false, 100, 200_000L, 2_000L, 100, false);

		Assert.assertEquals(3_600_000L, t.getFlips().get(0).holdMillis());
	}

	/**
	 * A slot we already have a record for, now holding something else, still
	 * baselines rather than books. Replacement is the ambiguous case — part of
	 * the predecessor may already be counted — and only "no record at all" is
	 * unambiguous enough to seed from.
	 */
	@Test
	public void aReplacementIsBaselinedNotSeeded()
	{
		FlipTracker t = new FlipTracker();
		t.setAccountHash(7L);
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_800L, 1_000, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 300, 540_000L, 1_800L, 1_000, false);
		Assert.assertEquals(300L, t.getOpenBuyTotals().get(1601)[0]);

		t = restart(t);
		t.setAccountHash(7L);
		// Same item and direction, re-listed higher: a different offer.
		Assert.assertNull(t.onOffer(3L, 0, 1601, "Diamond", true, 800, 1_520_000L, 1_900L, 1_000, false));
		Assert.assertEquals("nothing added by the replacement", 300L, t.getOpenBuyTotals().get(1601)[0]);
	}

	/**
	 * One sell offer, filled by the Exchange in five chunks, is five booked
	 * flips and ONE trade. This is the case off the report: 549 + 2 + 8 +
	 * 7,558 + 15 adamantite bars listed as five rows where it was one sale.
	 */
	@Test
	public void theFillsOfOneOfferShareAnOfferId()
	{
		FlipTracker t = new FlipTracker();
		t.setAccountHash(3L);
		// Buy the stock first, in one go.
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_000L, 8_132, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 8_132, 8_132_000L, 1_000L, 8_132, false);
		t.onOffer(3L, 0, 1601, "Diamond", true, 8_132, 8_132_000L, 1_000L, 8_132, true);

		// One sell offer, filled in five chunks.
		t.onOffer(10L, 1, 1601, "Diamond", false, 0, 0L, 1_100L, 8_132, false);
		int sold = 0;
		long gross = 0;
		for (int chunk : new int[]{549, 2, 8, 7_558, 15})
		{
			sold += chunk;
			gross += chunk * 1_100L;
			t.onOffer(20L + sold, 1, 1601, "Diamond", false, sold, gross, 1_100L, 8_132, false);
		}

		final List<Flip> booked = t.getFlips();
		Assert.assertEquals("still one flip per fill under the hood", 5, booked.size());

		final long offer = booked.get(0).offerId;
		Assert.assertTrue("fills carry an offer id", offer != 0);
		for (Flip f : booked)
		{
			Assert.assertEquals("all five came from the same offer", offer, f.offerId);
		}

		final List<Flip> trades = Flip.byTrade(booked);
		Assert.assertEquals("one trade", 1, trades.size());
		Assert.assertEquals(8_132, trades.get(0).quantity);
		// The merged row's money is exactly the parts' money.
		long partProfit = 0;
		for (Flip f : booked)
		{
			partProfit += f.profit;
		}
		Assert.assertEquals(partProfit, trades.get(0).profit);
		Assert.assertEquals(gross, trades.get(0).sellGross);

		// And the stats count the trade, not the chunks.
		FlipStats.Stats s = FlipStats.compute(booked, FlipStats.Range.ALL, 1_000_000L, 0L, 0L, 0L);
		Assert.assertEquals(1, s.flipCount);
		Assert.assertEquals(partProfit, s.profit);
	}

	/** A second offer for the same item is a second trade, however similar. */
	@Test
	public void twoOffersAreTwoTrades()
	{
		FlipTracker t = new FlipTracker();
		t.onOffer(1L, 0, 1601, "Diamond", true, 0, 0L, 1_000L, 200, false);
		t.onOffer(2L, 0, 1601, "Diamond", true, 200, 200_000L, 1_000L, 200, false);
		t.onOffer(3L, 0, 1601, "Diamond", true, 200, 200_000L, 1_000L, 200, true);

		for (int round = 0; round < 2; round++)
		{
			t.onOffer(10L + round * 10, 1, 1601, "Diamond", false, 0, 0L, 1_100L, 100, false);
			t.onOffer(11L + round * 10, 1, 1601, "Diamond", false, 100, 110_000L, 1_100L, 100, false);
			t.onOffer(12L + round * 10, 1, 1601, "Diamond", false, 100, 110_000L, 1_100L, 100, true);
		}

		Assert.assertEquals(2, Flip.byTrade(t.getFlips()).size());
		Assert.assertEquals(2, FlipStats.compute(t.getFlips(), FlipStats.Range.ALL,
			1_000_000L, 0L, 0L, 0L).flipCount);
	}

	/**
	 * Rows from before offers were tokenised carry 0, and a shared 0 must
	 * never collapse them all into one giant "trade".
	 *
	 * Different items are different trades however close together they close,
	 * which is the case that a naive "group by offerId" would get catastrophically
	 * wrong.
	 */
	@Test
	public void untokenisedRowsOfDifferentThingsStayApart()
	{
		final List<Flip> old = List.of(
			new Flip(1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(2_000L, 561, "Nature rune", 10, 1_000L, 1_100L, 22L),
			new Flip(3_000L, 1603, "Ruby", 10, 20_000L, 22_000L, 440L));
		Assert.assertEquals(3, Flip.byTrade(old).size());
		Assert.assertEquals(3, FlipStats.compute(old, FlipStats.Range.ALL,
			1_000_000L, 0L, 0L, 0L).flipCount);
	}

	/**
	 * An untokenised ledger still groups its split fills.
	 *
	 * offerId arrived on 15 Sep 2026, so every row booked before it is in the
	 * ledger with a zero and had nothing to group by. A real ledger reported
	 * nineteen rows for six trades — "some sold in batches of like 1000 of
	 * 18000 and it counted that 18 times" — while the website beside it said
	 * six, because the website never had a token and matched on the trade's
	 * own terms instead. Same terms here: same item, same unit price both
	 * sides, inside the window.
	 */
	@Test
	public void untokenisedSplitFillsGroupOnTheirTerms()
	{
		final List<Flip> fills = List.of(
			new Flip(1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(2_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(3_000L, 1601, "Diamond", 30, 30_000L, 33_000L, 660L));
		final List<Flip> trades = Flip.byTrade(fills);
		Assert.assertEquals("one offer, three fills", 1, trades.size());
		Assert.assertEquals("quantity is the sum", 50, trades.get(0).quantity);
		Assert.assertEquals("and so is the money",
			11_000L + 11_000L + 33_000L - 220L - 220L - 660L - 50_000L,
			trades.get(0).profit);
		Assert.assertEquals(1, FlipStats.compute(fills, FlipStats.Range.ALL,
			1_000_000L, 0L, 0L, 0L).flipCount);
	}

	/**
	 * The price test is what keeps genuinely separate decisions apart.
	 *
	 * Same item, same minute, different prices: two trades, because you chose
	 * twice. Merging on item alone would turn a day of trading one item into a
	 * single row.
	 */
	@Test
	public void untokenisedRowsAtDifferentPricesAreDifferentTrades()
	{
		final List<Flip> fills = List.of(
			new Flip(1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(2_000L, 1601, "Diamond", 10, 12_000L, 13_000L, 260L));
		Assert.assertEquals(2, Flip.byTrade(fills).size());
	}

	/** And the window keeps a re-entry at the same price later on apart from
	 *  the trade it resembles. */
	@Test
	public void untokenisedRowsOutsideTheWindowAreDifferentTrades()
	{
		final long hours3 = 3 * 3_600_000L;
		final List<Flip> fills = List.of(
			new Flip(1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(1_000L + hours3, 1601, "Diamond", 10, 10_000L, 11_000L, 220L));
		Assert.assertEquals(2, Flip.byTrade(fills).size());
	}

	/**
	 * A token is a fact and an inference must not overrule it.
	 *
	 * Two tokenised offers with identical terms a second apart stay two rows,
	 * because the client watched them being placed separately.
	 */
	@Test
	public void theTermsFallbackNeverOverridesARealToken()
	{
		final List<Flip> fills = List.of(
			new Flip(7L, 0L, 1_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(8L, 0L, 2_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L));
		Assert.assertEquals(2, Flip.byTrade(fills).size());
	}

	/** A merged hold time is unknown when ANY part's is — reporting the
	 *  earliest of the parts we happen to know would understate it. */
	@Test
	public void aMergedHoldIsUnknownIfAnyPartIs()
	{
		final List<Flip> parts = List.of(
			new Flip(7L, 0L, 5_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(7L, 1_000L, 6_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L));
		final Flip merged = Flip.merge(parts);
		Assert.assertEquals(-1L, merged.holdMillis());
		Assert.assertEquals(6_000L, merged.closedAt);
		Assert.assertEquals(20, merged.quantity);

		final List<Flip> known = List.of(
			new Flip(8L, 2_000L, 5_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L),
			new Flip(8L, 1_000L, 6_000L, 1601, "Diamond", 10, 10_000L, 11_000L, 220L));
		Assert.assertEquals("earliest capital commitment", 5_000L, Flip.merge(known).holdMillis());
	}

	/** An empty save is not an upgrade with history behind it — there are no
	 *  lots to double count, so a first sighting books as normal. */
	@Test
	public void anEmptySaveStillSeeds()
	{
		FlipTracker t = new FlipTracker();
		t.restore(new FlipTracker.State());
		Assert.assertNotNull(t.onOffer(1L, 0, 1601, "Diamond", true, 900, 1_620_000L, 1_800L, 1_000, false));
		Assert.assertEquals(900L, t.getOpenBuyTotals().get(1601)[0]);
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * The fill percentage on a GE slot tooltip. Every case here is a boundary,
 * which is the whole reason it is a pure static rather than a method buried
 * in a Swing component.
 */
public class GeSlotsPercentTest
{
	/** The case that prompted the change: a real fill against a five-figure
	 *  4-hour limit. As an integer this floored to "0", which says nothing
	 *  has happened about an offer that has genuinely started. */
	@Test
	public void aSmallFillAgainstABigLimitIsNotZero()
	{
		Assert.assertEquals("0.76", GeSlotsPanel.percentText(138, 18_000));
	}

	/** One item out of a huge limit is still a fill. It must not round away
	 *  to nothing — that is the same bug in a smaller number. */
	@Test
	public void aSingleItemNeverReportsAsZero()
	{
		Assert.assertEquals("0.01", GeSlotsPanel.percentText(1, 18_000));
		Assert.assertEquals("0.01", GeSlotsPanel.percentText(1, 1_000_000));
	}

	/** Nothing filled reads a flat 0 — "0.00%" for an offer that has not
	 *  moved is false precision. */
	@Test
	public void nothingFilledIsAFlatZero()
	{
		Assert.assertEquals("0", GeSlotsPanel.percentText(0, 18_000));
	}

	/** Whole numbers once there is a whole number to show. */
	@Test
	public void aboveOnePercentIsAWholeNumber()
	{
		Assert.assertEquals("1", GeSlotsPanel.percentText(180, 18_000));
		Assert.assertEquals("50", GeSlotsPanel.percentText(9_000, 18_000));
		Assert.assertEquals("33", GeSlotsPanel.percentText(6_000, 18_000));
	}

	/**
	 * Short of complete never reads 100. An offer 35,999 of 36,000 done is
	 * the one misreading that sends you to the GE for nothing.
	 */
	@Test
	public void almostDoneIsNeverAHundred()
	{
		Assert.assertEquals("99", GeSlotsPanel.percentText(35_999, 36_000));
		Assert.assertEquals("99", GeSlotsPanel.percentText(17_999, 18_000));
	}

	@Test
	public void completeIsAHundred()
	{
		Assert.assertEquals("100", GeSlotsPanel.percentText(18_000, 18_000));
		Assert.assertEquals("100", GeSlotsPanel.percentText(19_000, 18_000)); // over-fill clamps
	}

	/** Junk in, silence out — never a divide by zero or a negative. */
	@Test
	public void nonsenseInputsDoNotThrow()
	{
		Assert.assertEquals("0", GeSlotsPanel.percentText(5, 0));
		Assert.assertEquals("0", GeSlotsPanel.percentText(-5, 100));
		Assert.assertEquals("0", GeSlotsPanel.percentText(0, 0));
	}

	/** The crossover: just under 1% keeps decimals, exactly 1% does not. */
	@Test
	public void theCrossoverAtOnePercent()
	{
		Assert.assertEquals("0.99", GeSlotsPanel.percentText(99, 10_000));
		Assert.assertEquals("1", GeSlotsPanel.percentText(100, 10_000));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import org.junit.Assert;
import org.junit.Test;

/**
 * Everything Guice has to build, it can actually build.
 *
 * This exists because of a bug that took the whole plugin off the sidebar and
 * that nothing else here could have caught. A constant was added to
 * BankHighlightOverlay directly above its constructor:
 *
 *     &#64;Inject
 *     private static final int GE_INVENTORY_GROUP = 467;    // &lt;- new
 *     private BankHighlightOverlay() { ... }
 *
 * The annotation belonged to the constructor. The new field silently took it,
 * and both halves of that are fatal: Guice refuses an &#64;Inject on a final
 * field, and with the constructor no longer annotated it cannot build a class
 * whose only constructor is private. The injector dies at startup with a
 * CreationException, RuneLite drops the plugin, and the panel is simply gone.
 *
 * It compiles. It type-checks. Every unit test passes. Java is perfectly happy
 * to put an annotation on the wrong declaration, and the offline type-check
 * cannot run Guice at all — the one place the mistake shows up is a real
 * client, which is the slowest and most expensive place to find anything.
 *
 * So the rules Guice enforces at startup are enforced here instead, walking
 * the same graph Guice walks: start at the plugin, follow every &#64;Inject
 * into our own package, and check what it finds.
 */
public class InjectionWiringTest
{
	private static final String PKG = "com.pocketge.tracker.";

	/**
	 * The classes Guice is actually asked to construct — the transitive
	 * closure of our own types reachable through injection points, which is
	 * exactly the set whose wiring can break startup. A class nothing injects
	 * is not Guice's problem and is not checked.
	 */
	private static Set<Class<?>> injected()
	{
		final Set<Class<?>> seen = new LinkedHashSet<>();
		final Deque<Class<?>> queue = new ArrayDeque<>();
		queue.add(PocketGeTrackerPlugin.class);
		while (!queue.isEmpty())
		{
			final Class<?> c = queue.poll();
			if (c.isInterface() || c.isPrimitive() || !seen.add(c))
			{
				continue;
			}
			for (Field f : c.getDeclaredFields())
			{
				if (f.isAnnotationPresent(Inject.class) && ours(f.getType()))
				{
					queue.add(f.getType());
				}
			}
			for (Constructor<?> k : c.getDeclaredConstructors())
			{
				if (!k.isAnnotationPresent(Inject.class))
				{
					continue;
				}
				for (Class<?> p : k.getParameterTypes())
				{
					if (ours(p))
					{
						queue.add(p);
					}
				}
			}
		}
		return seen;
	}

	private static boolean ours(Class<?> c)
	{
		return c.getName().startsWith(PKG);
	}

	/**
	 * Guice: "Injected field cannot be final", and a static field is only
	 * injected on an explicit requestStaticInjection, which nothing here
	 * does. Either way the annotation is not doing what its author meant.
	 *
	 * This is the half of the bug that fires loudest — a CreationException
	 * naming the field — and the half that is hardest to read as a typo,
	 * because the field it names is not the declaration anyone touched.
	 */
	@Test
	public void noInjectedFieldIsStaticOrFinal()
	{
		final List<String> bad = new ArrayList<>();
		for (Class<?> c : injected())
		{
			for (Field f : c.getDeclaredFields())
			{
				if (!f.isAnnotationPresent(Inject.class))
				{
					continue;
				}
				if (Modifier.isStatic(f.getModifiers()))
				{
					bad.add(c.getSimpleName() + "." + f.getName() + " is static"
						+ " — did it steal the @Inject from the declaration below it?");
				}
				if (Modifier.isFinal(f.getModifiers()))
				{
					bad.add(c.getSimpleName() + "." + f.getName() + " is final"
						+ " — Guice refuses this and the injector dies at startup");
				}
			}
		}
		Assert.assertEquals(String.join("\n", bad), List.of(), bad);
	}

	/**
	 * And the quiet half: a class Guice must build needs either one &#64;Inject
	 * constructor or a zero-argument constructor it is allowed to call. Lose
	 * the annotation off a private constructor and there is nothing left —
	 * which is how the overlay stopped being constructible without a single
	 * line of its own code changing.
	 */
	@Test
	public void everyInjectedClassIsConstructible()
	{
		final List<String> bad = new ArrayList<>();
		for (Class<?> c : injected())
		{
			final Constructor<?>[] ctors = c.getDeclaredConstructors();
			int annotated = 0;
			boolean usableNoArg = false;
			for (Constructor<?> k : ctors)
			{
				if (k.isAnnotationPresent(Inject.class))
				{
					annotated++;
				}
				if (k.getParameterCount() == 0 && !Modifier.isPrivate(k.getModifiers()))
				{
					usableNoArg = true;
				}
			}
			if (annotated > 1)
			{
				bad.add(c.getSimpleName() + " has " + annotated + " @Inject constructors"
					+ " — Guice allows exactly one");
			}
			else if (annotated == 0 && !usableNoArg)
			{
				bad.add(c.getSimpleName() + " has no @Inject constructor and no callable"
					+ " zero-arg one — Guice cannot build it");
			}
		}
		Assert.assertEquals(String.join("\n", bad), List.of(), bad);
	}

	/**
	 * The walk has to actually reach things, or the two tests above pass by
	 * checking nothing — which is the failure mode of every test that scans
	 * for problems rather than asserting a value.
	 */
	@Test
	public void theWalkReachesTheOverlays()
	{
		final Set<Class<?>> seen = injected();
		Assert.assertTrue("the overlay that broke is in the set",
			seen.contains(BankHighlightOverlay.class));
		Assert.assertTrue("and the other two overlays",
			seen.contains(GeOfferGridOverlay.class) && seen.contains(GeOfferPriceOverlay.class));
		Assert.assertTrue("and the market client", seen.contains(MarketClient.class));
		Assert.assertTrue("and the bank legend, which is injected into nothing else",
			seen.contains(BankLegendOverlay.class));
	}

	/**
	 * The stub's @Inject must be RUNTIME or none of the above reads anything.
	 * It was CLASS-retention once, which is silent: the scans find no
	 * annotations, report no problems, and pass.
	 */
	@Test
	public void theAnnotationIsVisibleToReflection()
	{
		int found = 0;
		for (Field f : PocketGeTrackerPlugin.class.getDeclaredFields())
		{
			if (f.isAnnotationPresent(Inject.class))
			{
				found++;
			}
		}
		Assert.assertTrue("@Inject is not visible at runtime — these tests are inert", found > 5);
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

/**
 * Reading the Grand Exchange's own "N coins" readouts.
 *
 * The gold ring walks price -> quantity -> Confirm by asking whether the
 * running total the screen shows is target x quantity. That test used to
 * strip every non-digit from the line and parse the remainder as one number,
 * which works on a buy and cannot work on a sell: the Exchange prints a
 * sell's total NET of the 2% tax and puts the gross and the rate in brackets
 * after it.
 *
 * So the ring reached Confirm on a buy and stuck on the quantity control on a
 * sell no matter how complete the offer was — "it should be highlighting the
 * confirm now in this example. i already selected price and quantity".
 */
public class OfferReadoutTest
{
	/** The string that broke it, verbatim from the offer screen. */
	private static final String SELL_TOTAL = "8,502,000 coins (8,658,000 - 2%)";

	@Test
	public void findsTheGrossOnASellTotal()
	{
		Assert.assertTrue("the gross, which is target x quantity",
			GeOfferPriceOverlay.textShowsValue(SELL_TOTAL, 8_658_000L));
	}

	/** The old rule's actual output, pinned so nobody reinvents it. */
	@Test
	public void doesNotConcatenateEveryDigitOnTheLine()
	{
		Assert.assertFalse("850200086580002 is not a number on this screen",
			GeOfferPriceOverlay.textShowsValue(SELL_TOTAL, 850_200_086_580_002L));
	}

	/** The net is on the line too, and is a real number on it. */
	@Test
	public void findsTheNetAsWell()
	{
		Assert.assertTrue(GeOfferPriceOverlay.textShowsValue(SELL_TOTAL, 8_502_000L));
	}

	/** A buy has no bracket and never did break. */
	@Test
	public void stillReadsAPlainBuyTotal()
	{
		Assert.assertTrue(GeOfferPriceOverlay.textShowsValue("8,658,000 coins", 8_658_000L));
		Assert.assertTrue(GeOfferPriceOverlay.textShowsValue("333 coins", 333L));
	}

	/** And it is exact: a total that merely contains the digits is not a
	 *  match, or the ring would advance on a number nobody entered. */
	@Test
	public void doesNotMatchASubstringOfANumber()
	{
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue("8,658,000 coins", 658L));
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue("8,658,000 coins", 8_658L));
	}

	@Test
	public void refusesTheDegenerateCases()
	{
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue(null, 100L));
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue("100 coins", 0L));
		Assert.assertFalse(GeOfferPriceOverlay.textShowsValue("100 coins", -5L));
		Assert.assertFalse("no digits at all",
			GeOfferPriceOverlay.textShowsValue("Enter price", 100L));
	}

	/**
	 * A run of digits far too long to be gp does not throw — it is skipped and
	 * the scan carries on to the numbers that matter.
	 */
	@Test
	public void survivesANumberTooBigForALong()
	{
		Assert.assertTrue(GeOfferPriceOverlay.textShowsValue(
			"99999999999999999999999 coins (333 - 2%)", 333L));
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

public class PocketGeLinksTest
{
	@Test
	public void everyLinkIdentifiesItselfAsComingFromThePlugin()
	{
		for (String url : new String[]{
			PocketGeLinks.home("toolbar"),
			PocketGeLinks.home("bottom_link"),
			PocketGeLinks.flips("flip_history"),
			PocketGeLinks.item("Emerald%20necklace", "chart"),
		})
		{
			/* Every link is on the site and every link is tagged. Not all of
			   them are on the FRONT page any more — flip history has one of
			   its own — so this checks the host and the tags, which is what
			   the rule was ever about. */
			Assert.assertTrue(url, url.startsWith("https://pocketge.com/"));
			Assert.assertTrue(url, url.contains("utm_source=runelite"));
			Assert.assertTrue(url, url.contains("utm_medium=plugin"));
		}
	}

	/**
	 * q stays FIRST. The site reads that parameter to decide which item to
	 * open, and it is the half a human might read in the address bar; the
	 * tracking belongs behind it.
	 */
	@Test
	public void theItemNameStaysTheFirstParameter()
	{
		final String url = PocketGeLinks.item("Emerald%20necklace", "chart");
		Assert.assertEquals("https://pocketge.com/?q=Emerald%20necklace"
			+ "&utm_source=runelite&utm_medium=plugin&utm_content=chart", url);
		Assert.assertTrue("q must precede the tags",
			url.indexOf("q=") < url.indexOf("utm_"));
	}

	/** The whole point of utm_content: the chart button and the toolbar globe
	 *  have to be distinguishable once they arrive. */
	@Test
	public void eachControlIsDistinguishable()
	{
		Assert.assertTrue(PocketGeLinks.home("toolbar").endsWith("utm_content=toolbar"));
		Assert.assertTrue(PocketGeLinks.flips("flip_history").endsWith("utm_content=flip_history"));
		Assert.assertNotEquals(PocketGeLinks.home("toolbar"), PocketGeLinks.home("bottom_link"));
	}

	/**
	 * The flip-history link must NAME the history. It used to be home(), and
	 * the front page opens on whatever chart it opens on — so "Flip history"
	 * landed you on a chart for an item you had not asked about, with your
	 * flips nowhere in sight. It now names a page of its own; without that
	 * there is nothing to distinguish the click from the toolbar globe.
	 */
	@Test
	public void theFlipHistoryLinkAsksForTheFlipHistory()
	{
		final String url = PocketGeLinks.flips("flip_history");
		/* A page of its own now. It was "/?flips=1", which opened the front
		   page's Bank panel onto an all-flips list — the best available before
		   the page existed, and still answered by the site so older plugin
		   builds keep working. */
		Assert.assertEquals("https://pocketge.com/flip-history.html"
			+ "?utm_source=runelite&utm_medium=plugin&utm_content=flip_history", url);
		Assert.assertNotEquals("a link to the front page is not a link to your flips",
			PocketGeLinks.home("flip_history"), url);
		Assert.assertTrue("it names the page, not the front door",
			url.contains("flip-history.html"));
	}

	/** An encoded name must survive untouched — double-encoding it here would
	 *  open the wrong item, or none. */
	@Test
	public void anAlreadyEncodedNameIsNotEncodedAgain()
	{
		Assert.assertTrue(PocketGeLinks.item("Gold%20amulet%20(u)", "chart")
			.contains("q=Gold%20amulet%20(u)&"));
	}
}

