package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class PortfolioValuerTest
{
	private static Advisor.Quote quote(long low, long high)
	{
		Advisor.Quote q = new Advisor.Quote();
		q.low = low;
		q.high = high;
		return q;
	}

	/** netExit for the fixture quote(100, 110): the ask, less the 2% the
	 *  Exchange takes. 110 - 2 = 108. */
	private static final long NET_108 = 108;

	@Test
	public void cashAndItemsSumCorrectly()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, quote(100, 110));

		Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(1601, 50);

		PortfolioValuer.Result r = PortfolioValuer.value(1_000, holdings, new HashMap<>(), new ArrayList<>(), quotes);
		Assert.assertEquals(1_000L, r.cash);
		/* 50 x netExit, not 50 x low. Holdings used to be marked at the raw
		   bid with no tax — the wrong side of the book AND the wrong net,
		   which is not conservatism, just a different answer from the one the
		   sell card gives for the same stack. */
		Assert.assertEquals(50 * NET_108, r.itemsValue);
		Assert.assertEquals(0L, r.offersValue);
		Assert.assertEquals(1_000L + 50 * NET_108, r.total);
	}

	/**
	 * The property the whole netExit change exists for: what the header says
	 * a stack is worth and what the sell card offers for it are the same
	 * number.
	 *
	 * They were a full spread plus 2% apart, which on a thin book is easily
	 * enough to flip the sign — an unrealized loss in the header above a card
	 * promising a gain on the very same items. Asserted against the real
	 * Advisor rather than by re-deriving the arithmetic, so the two cannot
	 * drift apart again without this failing.
	 */
	@Test
	public void theHeaderAndTheSellCardAgreeOnWhatAStackIsWorth()
	{
		final Advisor.Quote q = quote(100, 110);
		q.highTime = 1_000_000L;
		q.lowTime = 1_000_000L;
		final Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, q);

		final Advisor.ItemMeta m = new Advisor.ItemMeta();
		m.id = 1601;
		m.name = "Diamond";
		m.limit = 10_000;
		m.dailyVolume = 1_000_000L;
		final Map<Integer, Advisor.ItemMeta> meta = new HashMap<>();
		meta.put(1601, m);

		final Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(1601, 5_000);

		final long headline = PortfolioValuer.value(0, holdings, new HashMap<>(), new ArrayList<>(), quotes).itemsValue;
		final Advisor.Suggestion card = Advisor.sellCandidates(1_000_000L, quotes, meta, holdings,
			new ArrayList<>(), new java.util.HashSet<>(), new java.util.HashSet<>(), null).get(0);

		Assert.assertEquals("the portfolio and the sell card price the same stack the same way",
			headline, card.grossValue);
		Assert.assertEquals(5_000 * NET_108, headline);
	}

	@Test
	public void unknownItemIsSkippedNotGuessed()
	{
		Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(999, 10); // no quote for this id
		PortfolioValuer.Result r = PortfolioValuer.value(0, holdings, new HashMap<>(), new ArrayList<>(), new HashMap<>());
		Assert.assertEquals(0L, r.itemsValue);
		Assert.assertEquals(0L, r.total);
	}

	@Test
	public void openBuyOfferCountsEscrowPlusFilledPortion()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, quote(100, 110));

		Advisor.OfferView buy = new Advisor.OfferView();
		buy.itemId = 1601;
		buy.buy = true;
		buy.price = 90;
		buy.totalQuantity = 100;
		buy.quantitySold = 40;
		buy.active = true;

		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(buy);

		PortfolioValuer.Result r = PortfolioValuer.value(0, new HashMap<>(), new HashMap<>(), offers, quotes);
		/* Unfilled 60 sits as gp in escrow at YOUR bid (60 x 90); the 40
		   already bought are items now, so they are worth what any other
		   stack of them is worth — netExit, like everything else. */
		Assert.assertEquals(60 * 90L + 40 * NET_108, r.offersValue);
	}

	@Test
	public void openSellOfferCountsUnsoldPlusProceedsAfterTax()
	{
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(1601, quote(100, 110));

		Advisor.OfferView sell = new Advisor.OfferView();
		sell.itemId = 1601;
		sell.buy = false;
		sell.price = 120;
		sell.totalQuantity = 50;
		sell.quantitySold = 30;
		sell.active = true;

		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(sell);

		PortfolioValuer.Result r = PortfolioValuer.value(0, new HashMap<>(), new HashMap<>(), offers, quotes);
		long tax = FlipTracker.taxPerItem(120, 1601) * 30;
		/* The 20 unsold are still your items, at netExit. The 30 already sold
		   are gp at the price YOU listed at, less the tax already taken —
		   that leg is a settled fact, not a valuation. */
		long expected = 20L * NET_108 + (30L * 120 - tax);
		Assert.assertEquals(expected, r.offersValue);
	}

	@Test
	public void inactiveOffersAreIgnored()
	{
		Advisor.OfferView inactive = new Advisor.OfferView();
		inactive.itemId = 1601;
		inactive.buy = true;
		inactive.price = 100;
		inactive.totalQuantity = 10;
		inactive.quantitySold = 10;
		inactive.active = false; // BOUGHT/CANCELLED — already collected or gone

		List<Advisor.OfferView> offers = new ArrayList<>();
		offers.add(inactive);

		PortfolioValuer.Result r = PortfolioValuer.value(0, new HashMap<>(), new HashMap<>(), offers, new HashMap<>());
		Assert.assertEquals(0L, r.offersValue);
	}

	/* ── heldPosition: the watchlist "profit available" tag ───────────────
	   Every test here exists because the alternative is a green number in
	   the player's sidebar telling them to go sell something, on a claim
	   that isn't true. */

	@Test
	public void heldPosition_holdingNothingReportsNothing()
	{
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(1601, 0, quote(100, 110), new long[]{5, 400});
		Assert.assertEquals(0, p.heldQty);
		Assert.assertEquals(0L, p.sellValue);
		Assert.assertFalse(p.hasCostBasis);
	}

	@Test
	public void heldPosition_noQuoteMeansNoClaim()
	{
		Assert.assertEquals(0L, PortfolioValuer.heldPosition(1601, 50, null, null).sellValue);
		Assert.assertEquals(0L, PortfolioValuer.heldPosition(1601, 50, quote(100, 0), null).sellValue);
	}

	@Test
	public void heldPosition_untrackedStackIsValuedButNeverCalledProfit()
	{
		// A stack owned before the plugin ever ran: worth something, but we
		// have no idea what it cost, so hasCostBasis must stay false and the
		// UI must not print "profit".
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(1601, 100, quote(1_000, 2_000), null);
		Assert.assertEquals(100, p.heldQty);
		// tax on 2000 = 2000/50 = 40; net 1960 each
		Assert.assertEquals(196_000L, p.sellValue);
		Assert.assertFalse(p.hasCostBasis);
		Assert.assertEquals(0L, p.heldProfit);
		Assert.assertEquals(0, p.pricedQty);
	}

	@Test
	public void heldPosition_trackedStackReportsGainAfterTax()
	{
		// Bought 100 at 1,500 each (150,000 spent), now bid 2,000.
		// net = 2000 - 40 = 1960 -> 196,000 proceeds - 150,000 = 46,000
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 100, quote(1_900, 2_000), new long[]{100, 150_000});
		Assert.assertTrue(p.hasCostBasis);
		Assert.assertEquals(100, p.pricedQty);
		Assert.assertEquals(196_000L, p.sellValue);
		Assert.assertEquals(46_000L, p.heldProfit);
	}

	@Test
	public void heldPosition_profitCoversOnlyTheUnitsStillHeld()
	{
		// Bought 1,000 and spent 150,000; used 400, so only 600 are left.
		// Claiming profit on all 1,000 would report gain on runes that are
		// gone. Cost of the 600 remaining = 150,000 * 0.6 = 90,000.
		// net = 2000 - 40 = 1960 -> 600 * 1960 = 1,176,000 - 90,000
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 600, quote(1_900, 2_000), new long[]{1_000, 150_000});
		Assert.assertEquals(600, p.heldQty);
		Assert.assertEquals(600, p.pricedQty);
		Assert.assertEquals(1_176_000L, p.sellValue);
		Assert.assertEquals(1_086_000L, p.heldProfit);
	}

	@Test
	public void heldPosition_profitCoversOnlyTheUnitsWeWatchedYouBuy()
	{
		// Held 500 but only ever saw 100 bought (400 pre-dated the plugin).
		// sellValue covers all 500; profit covers 100. Understating is the
		// only safe direction.
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 500, quote(1_900, 2_000), new long[]{100, 150_000});
		Assert.assertEquals(500, p.heldQty);
		Assert.assertEquals(100, p.pricedQty);
		Assert.assertEquals(980_000L, p.sellValue);        // 500 * 1960
		Assert.assertEquals(46_000L, p.heldProfit);        // 100 * 1960 - 150,000
	}

	@Test
	public void heldPosition_underwaterPositionReportsNegativeRatherThanZero()
	{
		// Bought 100 at 3,000 (300,000), now only bid 2,000. The panel
		// chooses not to SHOW this, but the number itself must be honest —
		// clamping here would hide a real loss from the inspection card too.
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 100, quote(1_900, 2_000), new long[]{100, 300_000});
		Assert.assertTrue(p.hasCostBasis);
		Assert.assertEquals(-104_000L, p.heldProfit);
	}

	@Test
	public void heldPosition_roundingNeverFlattersTheProfit()
	{
		// 3 of 7 units held, 100 gp spent on the 7. An average-cost-per-item
		// of 100/7 = 14 (integer truncation) would price the 3 at 42 and
		// claim 3 gp more profit than really exists. Ceil of 100*3/7 = 43.
		// Price is under the 50 gp tax floor, so net == high == 20.
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(
			1601, 3, quote(19, 20), new long[]{7, 100});
		Assert.assertEquals(3, p.pricedQty);
		Assert.assertEquals(60L, p.sellValue);
		Assert.assertEquals(17L, p.heldProfit); // 60 - 43, NOT 60 - 42
	}

	@Test
	public void heldPosition_zeroOrGarbageTrackedLotIsTreatedAsUntracked()
	{
		Assert.assertFalse(PortfolioValuer.heldPosition(1601, 50, quote(100, 200), new long[]{0, 0}).hasCostBasis);
		Assert.assertFalse(PortfolioValuer.heldPosition(1601, 50, quote(100, 200), new long[]{5, 0}).hasCostBasis);
		Assert.assertFalse(PortfolioValuer.heldPosition(1601, 50, quote(100, 200), new long[]{9}).hasCostBasis);
	}

	@Test
	public void heldPosition_taxExemptItemKeepsTheWholePrice()
	{
		// Chisel (1755) is on the tax-exempt list; net must equal the bid.
		PortfolioValuer.HeldPosition p = PortfolioValuer.heldPosition(1755, 10, quote(900, 1_000), null);
		Assert.assertEquals(10_000L, p.sellValue);
	}

	/* ── cash vs stock ────────────────────────────────────────────────────
	   Platinum tokens are how anyone flipping at size holds their gp. Counted
	   as an item they inflate "stock" and vanish from liquid cash, so the
	   advisor sizes buys against a fraction of the real bankroll. */

	@Test
	public void cashValue_knowsBothDenominations()
	{
		Assert.assertEquals(5_000L, PortfolioValuer.cashValue(PortfolioValuer.COINS_ID, 5_000));
		Assert.assertEquals(500_000_000L,
			PortfolioValuer.cashValue(PortfolioValuer.PLATINUM_TOKEN_ID, 500_000));
		Assert.assertEquals("an ordinary item is not cash", 0L, PortfolioValuer.cashValue(1601, 10));
		Assert.assertEquals(0L, PortfolioValuer.cashValue(PortfolioValuer.COINS_ID, 0));
		Assert.assertEquals(0L, PortfolioValuer.cashValue(PortfolioValuer.COINS_ID, -5));
	}

	@Test
	public void isCash_coversCoinsAndPlatinumOnly()
	{
		Assert.assertTrue(PortfolioValuer.isCash(PortfolioValuer.COINS_ID));
		Assert.assertTrue(PortfolioValuer.isCash(PortfolioValuer.PLATINUM_TOKEN_ID));
		Assert.assertFalse(PortfolioValuer.isCash(1601));
	}

	@Test
	public void cashLeftInHoldingsIsNeverCountedTwice()
	{
		// The plugin strips cash from holdings, but if a stray stack ever got
		// through it must not be added on top of the `cash` argument — and
		// platinum especially must not be valued from a market quote.
		Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		quotes.put(PortfolioValuer.PLATINUM_TOKEN_ID, quote(1_050, 1_100)); // market != face
		quotes.put(PortfolioValuer.COINS_ID, quote(1, 1));
		quotes.put(1601, quote(100, 110));

		Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(PortfolioValuer.PLATINUM_TOKEN_ID, 1_000);
		holdings.put(PortfolioValuer.COINS_ID, 50_000);
		holdings.put(1601, 50); // the only genuine stock here

		PortfolioValuer.Result r = PortfolioValuer.value(
			1_050_000L, holdings, new HashMap<>(), new ArrayList<>(), quotes);
		Assert.assertEquals("only the real item counts as stock", 50 * NET_108, r.itemsValue);
		Assert.assertEquals(1_050_000L, r.cash);
		Assert.assertEquals(1_050_000L + 50 * NET_108, r.total);
	}
}

package com.pocketge.tracker;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * The badge rules, pinned against pocketge.com's dayState(). Every threshold
 * here is one the website also enforces, so a change that quietly drifts the
 * plugin away from the site fails a test rather than showing the user two
 * different answers for the same item.
 */
public class PriceExtremesTest
{
	/** 1000-1200: a 20% range, comfortably past every range floor. */
	private static PriceExtremes fiveDay(long lo, long hi)
	{
		final PriceExtremes ex = new PriceExtremes();
		ex.lo5d = lo;
		ex.hi5d = hi;
		return ex;
	}

	@Test
	public void nothingAtAllWhenNoExtremesAreKnown()
	{
		assertEquals(PriceExtremes.Tier.NONE, new PriceExtremes().tier(1000, 990));
	}

	@Test
	public void topEightPercentOfTheFiveDayRangeIsAFiveDayHigh()
	{
		// Range 200 wide; 8% band = the top 16 gp, so 1184 and up.
		assertEquals(PriceExtremes.Tier.HIGH_5D, fiveDay(1000, 1200).tier(1184, 1100));
		assertEquals(PriceExtremes.Tier.NONE, fiveDay(1000, 1200).tier(1183, 1100));
	}

	@Test
	public void bottomEightPercentOfTheFiveDayRangeIsAFiveDayLow()
	{
		assertEquals(PriceExtremes.Tier.LOW_5D, fiveDay(1000, 1200).tier(1100, 1016));
		assertEquals(PriceExtremes.Tier.NONE, fiveDay(1000, 1200).tier(1100, 1017));
	}

	@Test
	public void aNearlyFlatItemNeverFlags()
	{
		/* 1000-1020 is a 2% range, under the 3% floor — without it, an item
		   that has not moved all week flags every time it ticks one gp. */
		final PriceExtremes flat = fiveDay(1000, 1020);
		assertEquals(PriceExtremes.Tier.NONE, flat.tier(1020, 1000));
	}

	@Test
	public void theDayTierNeedsThePriceToActuallyReachTheDaysExtreme()
	{
		final PriceExtremes ex = new PriceExtremes();
		ex.lo1d = 1000;
		ex.hi1d = 1100; // a 10% day range, past the 4% floor
		assertEquals(PriceExtremes.Tier.HIGH_1D, ex.tier(1100, 1050));
		assertEquals(PriceExtremes.Tier.HIGH_1D, ex.tier(1101, 1050)); // broke out
		assertEquals(PriceExtremes.Tier.NONE, ex.tier(1099, 1050));    // merely close
		assertEquals(PriceExtremes.Tier.LOW_1D, ex.tier(1050, 1000));
		assertEquals(PriceExtremes.Tier.NONE, ex.tier(1050, 1001));
	}

	@Test
	public void aQuietDayNeverFlagsEvenAtItsExactEdge()
	{
		final PriceExtremes ex = new PriceExtremes();
		ex.lo1d = 1000;
		ex.hi1d = 1030; // 3% — under the day tier's stricter 4% floor
		assertEquals(PriceExtremes.Tier.NONE, ex.tier(1030, 1000));
	}

	@Test
	public void aWiderWindowMakesTheBandEasierToLandIn_whichIsWhyThereIsNoThirtyDayTier()
	{
		/* This is the arithmetic that killed the 30-day badge, pinned so it
		   cannot be reintroduced by the same mistaken reasoning.

		   The band is 8% OF THE RANGE, so it scales WITH the range: a wide
		   window has a wide band and is EASIER to sit inside, not harder. A
		   price of 1,080 is inside the bottom band of the wide range and
		   nowhere near the narrow one, at the same instant, for the same
		   item. Stacked as a tier above 5-day it therefore fired on nearly
		   every row and buried the tier underneath it. */
		final PriceExtremes wide = fiveDay(1000, 2000);   // band = bottom 80gp
		final PriceExtremes narrow = fiveDay(1000, 1100); // band = bottom 8gp
		assertEquals(PriceExtremes.Tier.LOW_5D, wide.tier(1500, 1080));
		assertEquals(PriceExtremes.Tier.NONE, narrow.tier(1050, 1080));
	}

	@Test
	public void multiDayTiersOutrankTheDayTier()
	{
		final PriceExtremes ex = fiveDay(1000, 1200);
		ex.lo1d = 1000;
		ex.hi1d = 1190;
		// 1190 meets the day high AND sits in the 5-day top band.
		assertEquals(PriceExtremes.Tier.HIGH_5D, ex.tier(1190, 1100));
	}

	@Test
	public void anUnknownLivePriceCannotFlag()
	{
		/* A missing quote reads as 0, and 0 is below every low ever recorded.
		   Without the >0 guards that would badge the whole watchlist "at a
		   5-day low" the moment a price fetch came back empty. */
		final PriceExtremes ex = fiveDay(1000, 1200);
		ex.lo1d = 1000;
		ex.hi1d = 1100;
		assertEquals(PriceExtremes.Tier.NONE, ex.tier(0, 0));
	}

	@Test
	public void aMissingDayWindowDoesNotSuppressTheFiveDayAnswer()
	{
		/* The 1h fetch fills both windows at once, but a short series (a
		   newly tradeable item) can leave the day window empty. The 5-day
		   answer still has to come through. */
		final PriceExtremes ex = fiveDay(1000, 1200);
		ex.hi1d = 0;
		ex.lo1d = 0;
		assertEquals(PriceExtremes.Tier.HIGH_5D, ex.tier(1190, 1100));
	}

	@Test
	public void highAndLowAreJudgedOnTheirOwnSidesOfTheBook()
	{
		/* The insta-buy decides highs and the insta-sell decides lows, never
		   crossed. Each case puts exactly ONE side in its band and parks the
		   other mid-range, so a crossed comparison changes the answer. */
		final PriceExtremes ex = fiveDay(1000, 1200);
		assertEquals(PriceExtremes.Tier.HIGH_5D, ex.tier(1190, 1100));
		assertEquals(PriceExtremes.Tier.LOW_5D, ex.tier(1100, 1010));
	}

	@Test
	public void aWideSpreadTouchingBothEndsReadsAsAHigh()
	{
		/* An illiquid item can have an ask in the top band and a bid in the
		   bottom one at the same time. The website resolves that by testing
		   the high side first (app.js dayState), and the plugin has to agree
		   or the same item wears different badges in the two places. */
		final PriceExtremes ex = fiveDay(1000, 1200);
		assertEquals(PriceExtremes.Tier.HIGH_5D, ex.tier(1190, 1010));
	}
}

package com.pocketge.tracker;

import org.junit.Assert;
import org.junit.Test;

public class RangePositionTest
{
	private static RangePosition of(long lo, long hi, long opening)
	{
		final RangePosition r = new RangePosition();
		r.lo30 = lo;
		r.hi30 = hi;
		r.openingPrice = opening;
		return r;
	}

	/** The case that prompted the whole thing: Sapphire necklace, a real
	 *  30 gp spread, sitting at the top of a range it climbed 26% to reach. */
	@Test
	public void theSapphireNecklaceCaseReadsAsNearItsHigh()
	{
		final RangePosition r = of(426, 580, 452);
		Assert.assertTrue(r.usable());
		Assert.assertEquals(0.929, r.position(569), 0.002);
		Assert.assertEquals(25.9, r.runPct(569), 0.1);
		Assert.assertEquals("93% of 30d range · +26% in 30d", r.footnote(569));
	}

	/** Silence is the default. A card that says something about every item
	 *  says nothing about any of them. */
	@Test
	public void theMiddleOfTheRangeSaysNothing()
	{
		final RangePosition r = of(426, 580, 500);
		Assert.assertNull(r.footnote(500));
		Assert.assertNull(r.footnote(470));
		Assert.assertNull(r.footnote(530));
	}

	@Test
	public void theBottomOfTheRangeAlsoSpeaks()
	{
		final RangePosition r = of(426, 580, 560);
		Assert.assertEquals("7% of 30d range · -22% in 30d", r.footnote(437));
	}

	/**
	 * A flat item must not report "100% of its range".
	 *
	 * Arithmetically a 100-101 month puts 101 at the very top. It is also
	 * meaningless, and without this guard every stable item on the list would
	 * wear the loudest version of the badge.
	 */
	@Test
	public void anItemThatHasBarelyMovedHasNoUsableRange()
	{
		final RangePosition flat = of(100, 101, 100);
		Assert.assertFalse(flat.usable());
		Assert.assertEquals(-1, flat.position(101), 0.0001);
		Assert.assertNull(flat.footnote(101));
	}

	/** Exactly at the 5% floor is still too narrow; comfortably past it is not. */
	@Test
	public void theRangeFloorIsFivePercentOfTheHigh()
	{
		Assert.assertFalse("a 4.9% range is noise", of(951, 1000, 960).usable());
		Assert.assertTrue("a 10% range is real", of(900, 1000, 950).usable());
	}

	/**
	 * A live quote can legitimately sit above every completed bucket in the
	 * window — the range is history, the price is now.
	 */
	@Test
	public void aNewHighClampsToOneHundredPercentRatherThanOverflowing()
	{
		final RangePosition r = of(426, 580, 452);
		Assert.assertEquals(1.0, r.position(640), 0.0001);
		Assert.assertTrue(r.footnote(640).startsWith("100% of 30d range"));
	}

	/** "It did not move" and "we could not tell" are different claims. */
	@Test
	public void aMissingOpeningPriceIsNotAZeroPercentMove()
	{
		final RangePosition r = of(426, 580, 0);
		Assert.assertTrue(Double.isNaN(r.runPct(569)));
		Assert.assertEquals("no move to report, so the line carries only the position",
			"93% of 30d range", r.footnote(569));
	}

	/** A move too small to matter is left off rather than printed as +0%. */
	@Test
	public void aTinyMoveIsOmittedFromTheLine()
	{
		final RangePosition r = of(426, 580, 566);
		Assert.assertEquals("93% of 30d range", r.footnote(569));
	}

	@Test
	public void noDataMeansNoClaim()
	{
		final RangePosition empty = new RangePosition();
		Assert.assertFalse(empty.usable());
		Assert.assertNull(empty.footnote(569));
		Assert.assertEquals(-1, empty.position(569), 0.0001);
	}

	/* ── fromBuckets ─────────────────────────────────────────────────────── */

	@Test
	public void bucketsOutsideTheWindowAreIgnoredEntirely()
	{
		final long[] ts   = {100, 200, 300, 400};
		final long[] high = {900, 580, 560, 570};   // 900 is the stale one
		final long[] low  = {880, 426, 540, 560};
		final RangePosition r = RangePosition.fromBuckets(ts, high, low, 200);
		Assert.assertEquals("the pre-window 900 high must not widen the range", 580, r.hi30);
		Assert.assertEquals(426, r.lo30);
		Assert.assertEquals("opening is the first bucket INSIDE the window", 503, r.openingPrice);
	}

	/**
	 * A 6-hour bucket with no trades reports zero. That is an absence, not a
	 * price of nothing — treating it as a low would drag every range to 0 and
	 * make every item look like it was sitting on its high.
	 */
	@Test
	public void emptyBucketsDoNotDragTheRangeToZero()
	{
		final long[] ts   = {100, 200, 300};
		final long[] high = {580, 0, 570};
		final long[] low  = {520, 0, 540};
		final RangePosition r = RangePosition.fromBuckets(ts, high, low, 0);
		Assert.assertEquals(580, r.hi30);
		Assert.assertEquals(520, r.lo30);
	}

	@Test
	public void noBucketsYieldsNoClaim()
	{
		Assert.assertFalse(RangePosition.fromBuckets(null, null, null, 0).usable());
		Assert.assertFalse(RangePosition.fromBuckets(new long[0], new long[0], new long[0], 0).usable());
	}

	/** The line has to survive a 182px card. Longest realistic shape. */
	@Test
	public void theLineStaysShort()
	{
		final String longest = of(426, 580, 452).footnote(569);
		Assert.assertTrue("footnote was " + longest.length() + " chars: " + longest,
			longest.length() <= 32);
	}
}

package com.pocketge.tracker;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

/**
 * Every sell card the sidebar offers gets its price series fetched — not just
 * the first one.
 *
 * The plugin used to remember a single item id: whichever SELL Advisor.advise()
 * ranked top. But the sidebar does not show one sell, it shows the whole ranked
 * stack and lets you page through it — so card 1 was priced by TradeEngine and
 * cards 2..n were priced off the last insta-buy print, which is the
 * "quote the actively-traded price and call it a target" mistake the GE-context
 * path already had to be talked out of. Two cards in the same list, built by
 * two different methods, with nothing on either saying which one you got.
 *
 * Two things hold this closed. {@link #everySellCardOnTheBoardIsCovered} says
 * the selection is by rank and covers a board's worth rather than one item, and
 * {@link #aSeriesMovesTheAskOffTheRawPrint} says the coverage is worth having by
 * showing the two paths actually disagree.
 */
public class SellSeriesCoverageTest
{
	private static final long NOW = 1_700_000_000L;

	@Test
	public void everySellCardOnTheBoardIsCovered()
	{
		final List<AdvisorPanel.Rec> sells = new ArrayList<>();
		for (int i = 0; i < 20; i++)
		{
			final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
			r.sell = true;
			r.itemId = 1000 + i;
			sells.add(r);
		}

		final Set<Integer> ids = PocketGeTrackerPlugin.sellSeriesIds(sells);

		Assert.assertEquals("a board's worth, not one item",
			PocketGeTrackerPlugin.SELL_SERIES_CAP, ids.size());
		Assert.assertTrue("the top card is still in there", ids.contains(1000));
		Assert.assertTrue("and so is the one three pages down — this is the regression",
			ids.contains(1002));
		Assert.assertFalse("but not the twentieth: every id is an HTTP call per cycle",
			ids.contains(1019));
	}

	@Test
	public void aShortListIsCoveredWhole()
	{
		final List<AdvisorPanel.Rec> sells = new ArrayList<>();
		final AdvisorPanel.Rec r = new AdvisorPanel.Rec();
		r.sell = true;
		r.itemId = 1656;
		sells.add(r);

		Assert.assertEquals(new HashSet<>(java.util.Collections.singletonList(1656)),
			PocketGeTrackerPlugin.sellSeriesIds(sells));
	}

	@Test
	public void noSellsAsksForNothing()
	{
		Assert.assertTrue(PocketGeTrackerPlugin.sellSeriesIds(new ArrayList<>()).isEmpty());
	}

	/**
	 * The point of covering them: with a series the ask comes from the engine,
	 * without one it is the raw bid. If these ever coincide the test above is
	 * guarding nothing, so this asserts they differ.
	 */
	@Test
	public void aSeriesMovesTheAskOffTheRawPrint()
	{
		final Map<Integer, Advisor.Quote> quotes = new HashMap<>();
		final Advisor.Quote q = new Advisor.Quote();
		/* The bid sits below the series' own range, so the engine's target
		   clears it and sellTarget's never-under-the-bid clamp does not
		   simply hand back rawHigh — without that this test would pass on a
		   plugin that had no engine at all. */
		q.high = 1990;
		q.low = 1900;
		q.highTime = NOW;
		q.lowTime = NOW;
		quotes.put(1601, q);

		final Map<Integer, Advisor.ItemMeta> meta = new HashMap<>();
		final Advisor.ItemMeta m = new Advisor.ItemMeta();
		m.id = 1601;
		m.name = "Diamond";
		m.limit = 10_000;
		m.dailyVolume = 500_000;
		meta.put(1601, m);

		final Map<Integer, Integer> holdings = new HashMap<>();
		holdings.put(1601, 1_000);

		final Advisor.Suggestion raw = Advisor.sellCandidates(NOW, quotes, meta, holdings,
			new ArrayList<>(), new HashSet<>(), new HashSet<>(), null, new HashMap<>()).get(0);
		Assert.assertEquals("uncovered: the last insta-buy print, verbatim", 1990, raw.price);

		final Map<Integer, TradeEngine.Series> seriesByItem = new HashMap<>();
		seriesByItem.put(1601, AdvisorTest.syntheticSeries(NOW, 200, 1900, 2000, 11));
		final Advisor.Suggestion priced = Advisor.sellCandidates(NOW, quotes, meta, holdings,
			new ArrayList<>(), new HashSet<>(), new HashSet<>(), null, seriesByItem).get(0);

		Assert.assertNotEquals("covered: the engine's own target, as the website shows it",
			raw.price, priced.price);
		Assert.assertTrue("and never under the standing bid", priced.price >= q.high);
	}
}

package com.pocketge.tracker;

import java.awt.Color;
import org.junit.Assert;
import org.junit.Test;

/**
 * The sidebar strip and the in-game GE box agree about the same slot.
 *
 * Telling the plugin "I am pricing this one myself" muted the in-game box and
 * did nothing at all to the sidebar square, so the two surfaces described the
 * same offer differently — one saying "you have this in hand", the other
 * saying "priced fine", with no way to tell which was current.
 *
 * The data was already there. GeSlotsPanel.SlotInfo.adviceSkipped has been
 * populated all along; only the paint code ignored it, because the colour was
 * chosen from the STATE enum and "you are pricing this yourself" is not a
 * state — the offer is still perfectly active.
 */
public class SlotAccentTest
{
	private static GeSlotsPanel.SlotInfo slot(GeSlotsPanel.SlotState state, boolean skipped)
	{
		final GeSlotsPanel.SlotInfo s = new GeSlotsPanel.SlotInfo();
		s.state = state;
		s.adviceSkipped = skipped;
		return s;
	}

	@Test
	public void aSlotYouArePricingYourselfGoesMuted()
	{
		Assert.assertEquals("an offer priced fine, but yours to manage",
			GeSlotsPanel.MUTED_COLOR, GeSlotsPanel.accent(slot(GeSlotsPanel.SlotState.ACTIVE_OK, true)));
		Assert.assertEquals("and one the plugin would otherwise flag red",
			GeSlotsPanel.MUTED_COLOR, GeSlotsPanel.accent(slot(GeSlotsPanel.SlotState.ACTIVE_ADJUST, true)));
	}

	/**
	 * The muted grey is the SAME grey the in-game box uses. Two hand-written
	 * copies of a colour that has to match is how they stop matching, so
	 * there is one constant and this asserts the overlay still reads it.
	 */
	@Test
	public void bothSurfacesUseOneGrey()
	{
		Assert.assertEquals(new Color(0x8A, 0x82, 0x74), GeSlotsPanel.MUTED_COLOR);
	}

	/**
	 * Not a collectable slot. The flag outlives the offer it was set on, and
	 * muting a slot that is ready to collect would hide the one state that
	 * actually wants a click. The in-game overlay never meets this case
	 * because it drops inactive offers before painting.
	 */
	@Test
	public void aCollectableSlotIsNeverMuted()
	{
		Assert.assertEquals(GeSlotsPanel.COLLECT_COLOR,
			GeSlotsPanel.accent(slot(GeSlotsPanel.SlotState.READY_COLLECT, true)));
	}

	@Test
	public void nothingElseMoves()
	{
		Assert.assertEquals(GeSlotsPanel.OK_COLOR,
			GeSlotsPanel.accent(slot(GeSlotsPanel.SlotState.ACTIVE_OK, false)));
		Assert.assertEquals(GeSlotsPanel.ADJUST_COLOR,
			GeSlotsPanel.accent(slot(GeSlotsPanel.SlotState.ACTIVE_ADJUST, false)));
		Assert.assertEquals(GeSlotsPanel.COLLECT_COLOR,
			GeSlotsPanel.accent(slot(GeSlotsPanel.SlotState.READY_COLLECT, false)));
	}

	/** A null info is an empty square, not a crash. */
	@Test
	public void noOfferIsNotAColour()
	{
		Assert.assertNotNull(GeSlotsPanel.accent((GeSlotsPanel.SlotInfo) null));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Method;
import org.junit.Assert;
import org.junit.Test;

/**
 * The GE slot's hover says what to do, in a couple of words.
 *
 * It ran to six lines — item, "Buying N of M", projected profit, profit so
 * far, a diagnosis and an instruction. Every line was true and the whole was
 * no easier to read than the coloured border it existed to explain. The report
 * was "such a long hover tool tip … can't it just turn red and say something
 * like adjust price, or lower price, raise price, no margin".
 *
 * So: at most three lines, and the state line is a VERB. "Off the market"
 * named a problem and left you to go and find the number.
 */
public class SlotTooltipTest
{
	private static String tip(SlotShape shape) throws Exception
	{
		final Method m = GeOfferGridOverlay.class
			.getDeclaredMethod("tooltipText", GeOfferGridOverlay.SlotView.class);
		m.setAccessible(true);
		return (String) m.invoke(null, shape.view);
	}

	/** A slot, built by hand — SlotView is a plain data holder. */
	private static final class SlotShape
	{
		final GeOfferGridOverlay.SlotView view = new GeOfferGridOverlay.SlotView();

		SlotShape(boolean buy)
		{
			view.itemName = "Ruby";
			view.buy = buy;
			view.filled = 4_000;
			view.total = 12_328;
			view.offerPrice = 791;
		}

		SlotShape adjust(long target)
		{
			view.needsAdjust = true;
			view.targetPrice = target;
			return this;
		}

		SlotShape noMargin()
		{
			view.needsAdjust = true;
			view.noMargin = true;
			return this;
		}

		SlotShape skipped()
		{
			view.adviceSkipped = true;
			return this;
		}

		SlotShape profit(long p)
		{
			view.projectedProfit = p;
			return this;
		}
	}

	/** Lines, as the client counts them. */
	private static int lines(String tip)
	{
		return tip.split("</br>", -1).length;
	}

	@Test
	public void aMispricedSellSaysWhichWayToMoveAndToWhat() throws Exception
	{
		final String t = tip(new SlotShape(false).adjust(788).profit(145_000));
		Assert.assertTrue("names the direction: " + t, t.contains("Lower your ask to "));
		Assert.assertTrue("and the exact price, with separators", t.contains("788 gp"));
		Assert.assertTrue("and what you currently have in", t.contains("yours: 791"));
	}

	@Test
	public void aMispricedBuySaysTheOtherDirection() throws Exception
	{
		final String t = tip(new SlotShape(true).adjust(103).profit(80_000));
		Assert.assertTrue("a bid is always too LOW when it is wrong: " + t,
			t.contains("Raise your bid to "));
		Assert.assertFalse("never both", t.contains("Lower your ask"));
	}

	/**
	 * The green state now says something. It has always meant "not red",
	 * which is true and tells you nothing — reported as: I ignored the
	 * suggested price, typed my own, and the box stayed green, was it even
	 * listening? It was; the difference was inside the drift threshold.
	 */
	@Test
	public void aFineSlotSaysSoRatherThanJustNotBeingRed() throws Exception
	{
		final String t = tip(new SlotShape(false).profit(145_000));
		Assert.assertTrue("says it is fine: " + t, t.contains("Priced fine"));
		Assert.assertFalse("and does not ask for anything", t.contains("re-list"));
	}

	@Test
	public void noMarginSaysToWalkAwayRatherThanReprice() throws Exception
	{
		final String t = tip(new SlotShape(false).noMargin().profit(-4_000));
		Assert.assertTrue("no margin: " + t, t.contains("No margin left"));
		Assert.assertTrue("and what to do instead", t.contains("take a new flip"));
		Assert.assertFalse("repricing is the thing that does NOT help here",
			t.contains("Lower your ask"));
	}

	@Test
	public void aSlotYouArePricingYourselfSaysOnlyThat() throws Exception
	{
		final String t = tip(new SlotShape(false).skipped().profit(1));
		Assert.assertTrue(t.contains("You are pricing this one"));
		Assert.assertFalse("no instruction, because you turned them off",
			t.contains("Lower your ask") || t.contains("Priced fine"));
	}

	/** The whole point: it has to be SHORT. */
	@Test
	public void noShapeRunsPastThreeLines() throws Exception
	{
		Assert.assertTrue(lines(tip(new SlotShape(false).adjust(788).profit(145_000))) <= 3);
		Assert.assertTrue(lines(tip(new SlotShape(true).adjust(103).profit(80_000))) <= 3);
		Assert.assertTrue(lines(tip(new SlotShape(false).noMargin().profit(-4_000))) <= 3);
		Assert.assertTrue(lines(tip(new SlotShape(false).skipped().profit(1))) <= 3);
		Assert.assertTrue(lines(tip(new SlotShape(false).profit(145_000))) <= 3);
		/* And the one with no tracked cost, which is a different third line. */
		Assert.assertTrue(lines(tip(new SlotShape(false).adjust(788))) <= 3);
	}

	/**
	 * The lines that went, and must not creep back: the game already prints
	 * the quantity in the box, and "So far" is the same figure as the
	 * projection until an offer is part-filled.
	 */
	@Test
	public void theDuplicatedLinesAreGone() throws Exception
	{
		final SlotShape s = new SlotShape(false).adjust(788).profit(145_000);
		s.view.filledProfit = 40_000L;
		final String t = tip(s);
		Assert.assertFalse("the game prints this in the box itself: " + t, t.contains(" of "));
		Assert.assertFalse("a detail, not a verdict", t.contains("So far"));
	}

	/**
	 * A sell the plugin never watched being bought must not claim a profit
	 * measured from a cost of zero.
	 */
	@Test
	public void anUntrackedSellClaimsNoProfit() throws Exception
	{
		final String t = tip(new SlotShape(false).adjust(788));
		Assert.assertTrue("says why there is no figure: " + t, t.contains("Cost unknown"));
		Assert.assertFalse(t.contains("Profit:"));
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import org.junit.Assert;
import org.junit.Test;

/**
 * The sidebar square and the in-game GE box say the same words about the same
 * slot.
 *
 * There are two hovers, and both were long: the in-game one ran to six lines,
 * and the sidebar's was a single run-on sentence — "Selling Ruby — 4,000 of
 * 12,328 (32%) (needs a new price). The market moved to 788 gp; yours is at
 * 791 gp. Re-list at 788 gp — aborting keeps whatever already filled.
 * Right-click to stop being told to reprice it. Click to inspect it." Every
 * clause true, and nobody reads a paragraph off a 32px square.
 *
 * Both are three short lines now. The part worth a test is not the length but
 * the AGREEMENT: two surfaces describing the same eight slots, and a state
 * that is called one thing in the sidebar and another in the Exchange window
 * is worse than either wording on its own. Nothing in the compiler stops them
 * drifting, because they are different classes with different data holders.
 */
public class SlotWordingTest
{
	/** The verbs both surfaces have to use, for the states both can be in. */
	private static final String PRICED_FINE = "Priced fine";
	private static final String LOWER = "Lower your ask to ";
	private static final String RAISE = "Raise your bid to ";
	private static final String NO_MARGIN = "No margin left";
	private static final String YOURS = "You are pricing this one";

	// ---- the in-game box ---------------------------------------------------

	private static String inGame(boolean buy, boolean adjust, boolean noMargin,
		boolean skipped, long target) throws Exception
	{
		final GeOfferGridOverlay.SlotView v = new GeOfferGridOverlay.SlotView();
		v.itemName = "Ruby";
		v.buy = buy;
		v.needsAdjust = adjust;
		v.noMargin = noMargin;
		v.adviceSkipped = skipped;
		v.targetPrice = target;
		v.offerPrice = 791;
		final Method m = GeOfferGridOverlay.class
			.getDeclaredMethod("stateLine", GeOfferGridOverlay.SlotView.class);
		m.setAccessible(true);
		return strip((String) m.invoke(null, v));
	}

	// ---- the sidebar square ------------------------------------------------

	private static String sidebar(boolean buy, GeSlotsPanel.SlotState state, boolean noMargin,
		boolean skipped, long target) throws Exception
	{
		final GeSlotsPanel.SlotInfo s = new GeSlotsPanel.SlotInfo();
		s.itemName = "Ruby";
		s.buy = buy;
		s.state = state;
		s.noMargin = noMargin;
		s.adviceSkipped = skipped;
		s.targetPrice = target;
		s.offerPrice = 791;

		/* The cell is a private inner class and its stateLine is an instance
		   method on it. Reached reflectively rather than widening either for
		   a test. */
		final Class<?> cell = Class.forName("com.pocketge.tracker.GeSlotsPanel$Cell");
		final Constructor<?> ctor = cell.getDeclaredConstructors()[0];
		ctor.setAccessible(true);
		final Object instance = alloc(cell);
		final Method m = cell.getDeclaredMethod("stateLine", GeSlotsPanel.SlotInfo.class);
		m.setAccessible(true);
		return strip((String) m.invoke(instance, s));
	}

	private static Object alloc(Class<?> c) throws Exception
	{
		final java.lang.reflect.Field f = sun.misc.Unsafe.class.getDeclaredField("theUnsafe");
		f.setAccessible(true);
		final sun.misc.Unsafe unsafe = (sun.misc.Unsafe) f.get(null);
		return unsafe.allocateInstance(c);
	}

	/** The in-game text carries RuneScape colour tags; the sidebar's does not.
	 *  Compare the words, not the markup. */
	private static String strip(String s)
	{
		return s.replaceAll("<[^>]*>", "").trim();
	}

	// ---- the agreement -----------------------------------------------------

	@Test
	public void bothCallAFineSlotTheSameThing() throws Exception
	{
		Assert.assertTrue(inGame(false, false, false, false, 0).startsWith(PRICED_FINE));
		Assert.assertTrue(
			sidebar(false, GeSlotsPanel.SlotState.ACTIVE_OK, false, false, 0).startsWith(PRICED_FINE));
	}

	@Test
	public void bothTellYouWhichWayToMoveASell() throws Exception
	{
		final String a = inGame(false, true, false, false, 788);
		final String b = sidebar(false, GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, false, 788);
		Assert.assertTrue("in-game: " + a, a.startsWith(LOWER) && a.contains("788"));
		Assert.assertTrue("sidebar: " + b, b.startsWith(LOWER) && b.contains("788"));
		Assert.assertTrue("both show what you have in now",
			a.contains("791") && b.contains("791"));
	}

	@Test
	public void bothTellYouWhichWayToMoveABuy() throws Exception
	{
		Assert.assertTrue(inGame(true, true, false, false, 103).startsWith(RAISE));
		Assert.assertTrue(
			sidebar(true, GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, false, 103).startsWith(RAISE));
	}

	@Test
	public void bothSayNoMarginRatherThanReprice() throws Exception
	{
		final String a = inGame(false, true, true, false, 0);
		final String b = sidebar(false, GeSlotsPanel.SlotState.ACTIVE_ADJUST, true, false, 0);
		Assert.assertTrue(a.startsWith(NO_MARGIN));
		Assert.assertTrue(b.startsWith(NO_MARGIN));
		Assert.assertFalse("repricing is the thing that does not help here", a.contains(LOWER));
		Assert.assertFalse(b.contains(LOWER));
	}

	@Test
	public void bothSayWhenYouHaveTakenTheSlotOver() throws Exception
	{
		Assert.assertTrue(inGame(false, true, false, true, 788).startsWith(YOURS));
		Assert.assertTrue(
			sidebar(false, GeSlotsPanel.SlotState.ACTIVE_ADJUST, false, true, 788).startsWith(YOURS));
	}

	/**
	 * Only the sidebar has this one: the in-game overlay never draws a
	 * collected offer, because buildSlotViews drops inactive ones before it
	 * gets there. So it is checked on the surface that has it.
