package com.pocketge.tracker;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Assert;
import org.junit.Test;

/**
 * The two in-game tooltips speak one vocabulary.
 *
 * They did not. Each overlay wrote its own colours as hex literals inside the
 * markup, so the bank's tooltip was fixed and tested while the Exchange's kept
 * the exact brown the bank had just been rid of — {@code 8a8274}, two shades
 * off the tooltip's own background — on four of its lines.
 *
 * The test reads the sources, because that is where the defect lives: a hex
 * literal beside a {@link java.awt.Color} constant holding the same value is
 * the thing that let the border and the sentence explaining the border be
 * changed apart.
 */
public class TipStyleTest
{
	private static final List<String> OVERLAYS = List.of(
		"BankHighlightOverlay", "GeOfferGridOverlay");

	/**
	 * The class's CODE, with comments stripped.
	 *
	 * The comments name the colours that were removed, and are the record of
	 * why — deleting them to satisfy a grep would throw away the only account
	 * of a defect that has now been introduced twice.
	 */
	private static String source(String cls) throws IOException
	{
		final String raw = Files.readString(
			Path.of("src/main/java/com/pocketge/tracker/" + cls + ".java"));
		return raw.replaceAll("(?s)/\\*.*?\\*/", " ").replaceAll("(?m)//.*$", " ");
	}

	/**
	 * No colour is spelled out inside the markup any more.
	 *
	 * {@code <col=} followed by six hex digits is the whole bug class: it
	 * cannot be found by a compiler, cannot be moved with the theme, and reads
	 * as the same kind of thing whether it matches a constant or not.
	 */
	@Test
	public void noOverlayWritesAColourAsHex() throws Exception
	{
		final Pattern lit = Pattern.compile("<col=[0-9a-fA-F]{6}");
		for (String cls : OVERLAYS)
		{
			final Matcher m = lit.matcher(source(cls));
			Assert.assertFalse(cls + " still writes a colour into its markup: "
				+ (m.find() ? m.group() : ""), m.reset().find());
		}
	}

	/**
	 * The unreadable brown is gone from BOTH surfaces, not just the one that
	 * was reported.
	 */
	@Test
	public void theBrownIsGoneEverywhere() throws Exception
	{
		for (String cls : OVERLAYS)
		{
			Assert.assertFalse(cls + " still uses the 8a8274 brown",
				source(cls).toLowerCase().contains("8a8274"));
		}
		Assert.assertFalse("and the shared muted colour is not it",
			TipStyle.hex(TipStyle.MUTED).equals("8a8274"));
	}

	/**
	 * The near-gold that titled every Exchange tooltip is gone.
	 *
	 * e5c158 was not the theme's buy gold (E5B842), not the parchment the
	 * sidebar names items in, and not any other colour in the plugin — close
	 * enough to several to look deliberate and match none of them.
	 */
	@Test
	public void theNearMissGoldIsGone() throws Exception
	{
		Assert.assertFalse(source("GeOfferGridOverlay").toLowerCase().contains("e5c158"));
	}

	/** An item's name is parchment on every surface — the sidebar's TEXT_MAIN. */
	@Test
	public void namesTheSubjectInTheSameColourTheSidebarDoes()
	{
		Assert.assertEquals("d9d3c7", TipStyle.hex(TipStyle.SUBJECT));
		Assert.assertTrue(TipStyle.subject("Uncut ruby").contains("<col=d9d3c7>"));
	}

	/** The working is muted, and legibly so. */
	@Test
	public void mutesTheWorking()
	{
		Assert.assertEquals("a5a5a5", TipStyle.hex(TipStyle.MUTED));
	}

	/**
	 * Money keeps the sidebar's own green and red, and carries its sign.
	 *
	 * Same values as AdvisorPanel.POSITIVE and NEGATIVE, so a loss is the same
	 * red in the Exchange as on the card describing the same offer.
	 */
	@Test
	public void aGainAndALossWearTheSidebarsColours()
	{
		Assert.assertEquals(0x1FB85C, TipStyle.GOOD.getRGB() & 0xFFFFFF);
		Assert.assertEquals(0xEF5350, TipStyle.BAD.getRGB() & 0xFFFFFF);
		Assert.assertTrue(TipStyle.money(1_100_000).contains("+1.1M gp"));
		Assert.assertTrue(TipStyle.money(1_100_000).contains("1fb85c"));
		Assert.assertTrue(TipStyle.money(-250_000).contains("ef5350"));
		Assert.assertFalse("a loss needs no plus sign", TipStyle.money(-250_000).contains("+"));
	}

	/**
	 * A state line takes the colour of the mark it explains, from the caller.
	 *
	 * This is the one colour TipStyle refuses to choose. The bank's marks move
	 * with the theme and the Exchange's borders do not, and a tooltip that
	 * picked its own would be free to disagree with the square under the
	 * cursor — which is exactly how the bank ended up printing a frozen teal
	 * line under three themes that had moved.
	 */
	@Test
	public void aStateLineWearsTheMarksOwnColour()
	{
		final java.awt.Color neon = PocketGeTrackerConfig.ColourTheme.NEON.sell();
		Assert.assertTrue(TipStyle.state(neon, "up 12%").contains(TipStyle.hex(neon)));
	}

	/** Game markup, not HTML: the break is {@code </br>}. A {@code <br>} here
	 *  prints as four literal characters in the client. */
	@Test
	public void usesTheGamesOwnLineBreak()
	{
		Assert.assertEquals("</br>", TipStyle.BREAK);
		for (String cls : OVERLAYS)
		{
			try
			{
				Assert.assertFalse(cls + " uses an HTML break",
					source(cls).contains("\"<br>\""));
			}
			catch (IOException e)
			{
				throw new AssertionError(e);
			}
		}
	}
}

package com.pocketge.tracker;

import java.util.Random;
import org.junit.Assert;
import org.junit.Test;

public class TradeEngineTest
{
	private static TradeEngine.Series syntheticSeries(long now, int n, double baseLow, double baseHigh, long seed)
	{
		Random rnd = new Random(seed);
		TradeEngine.Series s = new TradeEngine.Series();
		s.labels = new long[n];
		s.low = new double[n];
		s.high = new double[n];
		s.lowVol = new double[n];
		s.highVol = new double[n];
		double low = baseLow, high = baseHigh;
		for (int i = 0; i < n; i++)
		{
			low += rnd.nextInt(3) - 1;
			high += rnd.nextInt(3) - 1;
			if (high < low + 40)
			{
				high = low + 40; // keep a real spread — 2% tax must stay clearable
			}
			s.labels[i] = now - (long) (n - 1 - i) * 300L;
			s.low[i] = low;
			s.high[i] = high;
			s.lowVol[i] = 50 + rnd.nextInt(200);
			s.highVol[i] = 50 + rnd.nextInt(200);
		}
		return s;
	}

	@Test
	public void nullSeriesFallsBackToRawQuote()
	{
		TradeEngine.Result r = TradeEngine.compute(836, 845, 1_000_000L, 1_000_000L, null, 1618);
		Assert.assertFalse(r.viable);
		Assert.assertEquals(836, r.buy);
		Assert.assertEquals(845, r.sell);
		Assert.assertTrue(r.lowConf);
	}

	@Test
	public void tooFewBucketsFallsBackToRawQuote()
	{
		TradeEngine.Series series = syntheticSeries(1_000_000L, 5, 800, 820, 42);
		TradeEngine.Result r = TradeEngine.compute(805, 815, 1_000_000L, 1_000_000L, series, 1618);
		Assert.assertFalse(r.viable);
		Assert.assertEquals(805, r.buy);
		Assert.assertEquals(815, r.sell);
	}

	@Test
	public void viableSeriesProducesSensibleFillableSpread()
	{
		int n = 200;
		long now = 1_000_000L;
		TradeEngine.Series series = syntheticSeries(now, n, 800, 850, 7);
		TradeEngine.Result r = TradeEngine.compute((long) series.low[n - 1], (long) series.high[n - 1], now, now, series, 1618);
		Assert.assertTrue(r.viable);
		Assert.assertTrue(r.buy > 0);
		Assert.assertTrue(r.sell > r.buy);
		Assert.assertTrue(r.edge >= TradeEngine.minEdge(r.buy));
	}

	@Test
	public void minEdgeScalesWithPriceAndHasAFloor()
	{
		Assert.assertEquals(2, TradeEngine.minEdge(100));
		Assert.assertTrue(TradeEngine.minEdge(1_000_000) > 2);
	}

	/* ── sellTarget / buyTarget: never quote the wrong side of the book ───
	   Regression cover for the live Yew logs case: insta-buy was 115, the
	   engine returned a 107/111 flip pair, and the offer screen told the
	   player to SELL at 111 — 4 gp under a standing bid, and disagreeing
	   with both pocketge.com and Flipping Copilot on the same screen. */

	@Test
	public void sellTarget_neverQuotesUnderTheStandingBid()
	{
		Assert.assertEquals(115L, TradeEngine.sellTarget(111L, 115L)); // the Yew logs case
	}

	@Test
	public void sellTarget_leavesAHigherAskAlone()
	{
		// Asking above the bid is the normal patient sell — not clamped down.
		Assert.assertEquals(120L, TradeEngine.sellTarget(120L, 115L));
		Assert.assertEquals(115L, TradeEngine.sellTarget(115L, 115L));
	}

	@Test
	public void sellTarget_withoutAQuoteChangesNothing()
	{
		Assert.assertEquals(111L, TradeEngine.sellTarget(111L, 0L));
		Assert.assertEquals(111L, TradeEngine.sellTarget(111L, -1L));
	}

	@Test
	public void buyTarget_neverBidsOverTheStandingAsk()
	{
		Assert.assertEquals(112L, TradeEngine.buyTarget(120L, 112L));
	}

	@Test
	public void buyTarget_leavesALowerBidAlone()
	{
		// Bidding under the ask is the normal patient buy — not clamped up.
		Assert.assertEquals(111L, TradeEngine.buyTarget(111L, 112L));
		Assert.assertEquals(112L, TradeEngine.buyTarget(112L, 112L));
	}

	@Test
	public void buyTarget_withoutAQuoteChangesNothing()
	{
		Assert.assertEquals(120L, TradeEngine.buyTarget(120L, 0L));
	}

	@Test
	public void clampedPairStillLeavesTheSpreadIntact()
	{
		// Whatever the engine picked, the clamped pair must never cross:
		// buy <= insta-sell <= insta-buy <= sell.
		final long rawLow = 112, rawHigh = 115;
		long b = TradeEngine.buyTarget(107L, rawLow);
		long s = TradeEngine.sellTarget(111L, rawHigh);
		Assert.assertTrue("buy " + b + " must not exceed insta-sell " + rawLow, b <= rawLow);
		Assert.assertTrue("sell " + s + " must not undercut insta-buy " + rawHigh, s >= rawHigh);
		Assert.assertTrue("clamped pair crossed: buy " + b + " >= sell " + s, b < s);
	}
}

package com.pocketge.tracker;

import java.lang.reflect.Proxy;
import java.util.EnumSet;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import org.junit.Assert;
import org.junit.Test;

/**
 * How many Grand Exchange slots a world lets you use.
 *
 * The number was right in the advice text and wrong in the slot overlay,
 * because only one of them asked. On a free world the client reports the
 * five members-only slots as EMPTY — present in the interface, just locked —
 * and the overlay walked all eight looking for the first empty one, so the
 * "start your offer here" ring landed on a slot the player could not open:
 * "its trying to tell me to use a ge slot i dont have".
 */
public class UsableGeSlotsTest
{
	/**
	 * A Client that answers getWorldType and nothing else, as a dynamic proxy.
	 *
	 * NOT {@code new Client(){ ... }}. The first version of this test did
	 * that, and it compiled against the offline stub — whose methods all had
	 * default bodies — and then failed the real Gradle build, where Client
	 * has several hundred abstract methods. BankHighlightOverlayTest had
	 * already hit and documented the identical mistake, in the same
	 * directory. The stub is abstract now, so the anonymous form no longer
	 * compiles anywhere; a proxy is shaped by the interface at runtime and
	 * cannot fall out of step with either version of it.
	 */
	private static Client world(EnumSet<WorldType> types)
	{
		return (Client) Proxy.newProxyInstance(
			Client.class.getClassLoader(),
			new Class<?>[]{Client.class},
			(proxy, method, args) ->
			{
				if ("getWorldType".equals(method.getName()))
				{
					return types;
				}
				final Class<?> r = method.getReturnType();
				if (r == boolean.class)
				{
					return false;
				}
				if (r.isPrimitive())
				{
					return 0;
				}
				return null;
			});
	}

	private static Client free()
	{
		return world(EnumSet.noneOf(WorldType.class));
	}

	private static Client members()
	{
		return world(EnumSet.of(WorldType.MEMBERS));
	}

	@Test
	public void aFreeWorldHasThree()
	{
		Assert.assertEquals(3, PocketGeTrackerPlugin.usableGeSlots(free()));
	}

	@Test
	public void aMembersWorldHasEight()
	{
		Assert.assertEquals(8, PocketGeTrackerPlugin.usableGeSlots(members()));
	}

	/** Before the client knows what world it is on, assume the smaller
	 *  number — a ring on a slot you cannot use is worse than no ring. */
	@Test
	public void unknownWorldIsTreatedAsFree()
	{
		Assert.assertEquals(3, PocketGeTrackerPlugin.usableGeSlots(null));
		Assert.assertEquals(3, PocketGeTrackerPlugin.usableGeSlots(world(null)));
	}

	/** The two constants the rest of the plugin sizes against are the same
	 *  numbers this returns, so the advice and the overlay cannot disagree. */
	@Test
	public void agreesWithTheSizingConstants()
	{
		Assert.assertEquals(PocketGeTrackerPlugin.F2P_GE_SLOTS,
			PocketGeTrackerPlugin.usableGeSlots(free()));
		Assert.assertEquals(PocketGeTrackerPlugin.MEMBERS_GE_SLOTS,
			PocketGeTrackerPlugin.usableGeSlots(members()));
	}
}

